INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---return-of-the-sinister-six-usa', 'NES', 'Spider-Man - Return of the Sinister Six (USA)', '1992', 'Action, Platformer', 'Bits Studios', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the Sinister Six to save New York.', 'The definitive US version of the Spidey adventure.', 'It features a limited supply of web fluid, forcing players to use their wall-crawling and melee skills strategically.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spiderman-2', 'NES', 'Spiderman 2', '1991', 'Action, Platformer', 'Unknown', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop Doc Ock and his henchmen.', 'A fan-made hack or bootleg sequel.', 'Usually based on the engine of another game, it provides custom levels and sprites to give Spider-Man a "new" 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spiritual-warfare-usa-unl-beta', 'NES', 'Spiritual Warfare (USA) (Unl) (Beta)', '1993', 'Action, Adventure', 'Wisdom Tree', '1', 'Top-down', 'Action / Adventure.', 'Collect the Armor of God to defeat the devil.', 'An unreleased preview of the Christian action game.', 'An unlicensed title by Wisdom Tree that plays very similarly to The Legend of Zelda, but with biblical themes and items.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spiritual-warfare-usa-unl-v51', 'NES', 'Spiritual Warfare (USA) (Unl) (v5.1)', '1993', 'Action, Adventure', 'Wisdom Tree', '1', 'Top-down', 'Action / Adventure.', 'Use fruits of the spirit to convert enemies.', 'An early retail version of the biblical adventure.', 'Players explore a modern city, solving puzzles and "cleansing" thugs and demons using religious items like the Jawbone of a Donkey.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spiritual-warfare-usa-unl-v60', 'NES', 'Spiritual Warfare (USA) (Unl) (v6.0)', '1993', 'Action, Adventure', 'Wisdom Tree', '1', 'Top-down', 'Action / Adventure.', 'Defeat the forces of darkness in the city.', 'An updated unlicensed release with minor fixes.', 'This version polishes some of the puzzle logic and inventory management found in the earlier 5.1 production run.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spiritual-warfare-usa-unl-v61', 'NES', 'Spiritual Warfare (USA) (Unl) (v6.1)', '1993', 'Action, Adventure', 'Wisdom Tree', '1', 'Top-down', 'Action / Adventure.', 'Defeat the forces of darkness in the city.', 'The final polished version of the Wisdom Tree hit.', 'Includes the most stable code and final dialogue tweaks for this ambitious unlicensed open-world adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('splatter-house---wanpaku-graffiti-japan', 'NES', 'Splatter House - Wanpaku Graffiti (Japan)', '1989', 'Action, Platformer', 'Namco', '1', 'Side-scrolling', 'Side-scrolling action.', 'Rescue your girlfriend Jennifer from the monsters.', 'A comedic, "chibi" take on the horror franchise.', 'Despite the cute graphics, it''s a solid action game full of movie parodies (like Jason Voorhees or Alien) and great boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('splatter-house---wanpaku-graffiti-japan-en-by-spinner-8-v20-~sd-splatterhouse', 'NES', 'Splatter House - Wanpaku Graffiti (Japan) [En by Spinner 8 v2.0] (~SD Splatterhouse)', '1989', 'Action, Platformer', 'Namco', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop the monsters with fully translated text.', 'The English fan translation of Wanpaku Graffiti.', 'It translates all the funny dialogue and the "secret" ending, making the horror movie jokes accessible to everyone.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spot---the-video-game-japan', 'NES', 'Spot - The Video Game (Japan)', '1991', 'Action', 'Nintendo', '1', 'Side-scrolling', 'Board Game / Puzzle.', 'Outmaneuver your opponent to cover the board.', 'A branded version of the board game "Ataxx."', 'Featuring the 7-Up mascot, players jump or multiply their pieces to dominate the grid in a deep strategy challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spot---the-video-game-usa', 'NES', 'Spot - The Video Game (USA)', '1991', 'Action', 'Nintendo', '1', 'Side-scrolling', 'Board Game / Puzzle.', 'Outmaneuver your opponent to cover the board.', 'The North American release of the 7-Up strategy game.', 'It features fun animations for the Spot characters and multiple difficulty levels for the computer AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-hunter-usa', 'NES', 'Spy Hunter (USA)', '1987', 'Action, Shooter', 'Bally Midway', '1', 'Top-down', 'Combat Racing.', 'Destroy enemy vehicles while protecting civilians.', 'A classic overhead arcade port by Bally Midway.', 'Your car can transform into a boat and features upgrades like oil slicks, smoke screens, and missiles delivered by a supply truck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-vs-spy-europe', 'NES', 'Spy vs Spy (Europe)', '1988', 'Action, Strategy', 'First Star Software', '2', 'Top-down', 'Strategy / Action.', 'Find the secret items and escape before your rival.', 'A brilliant split-screen trap-laying game.', 'Based on the MAD Magazine comic, players must search a building for loot while setting lethal traps for each other in real-time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-vs-spy-japan', 'NES', 'Spy vs Spy (Japan)', '1988', 'Action, Strategy', 'First Star Software', '2', 'Top-down', 'Strategy / Action.', 'Outsmart the other spy in this tactical duel.', 'The Famicom version of the iconic comic game.', 'Known for its addictive 2-player mode where players must remember which furniture they''ve booby-trapped.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-vs-spy-usa', 'NES', 'Spy vs Spy (USA)', '1988', 'Action, Strategy', 'First Star Software', '2', 'Top-down', 'Strategy / Action.', 'Find the items and reach the airport first.', 'The definitive US version of the spy classic.', 'A masterclass in 8-bit competitive play, featuring the White Spy and Black Spy in an endless loop of slapstick violence.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sqoon-japan', 'NES', 'Sqoon (Japan)', '1986', 'Action, Shooter', 'Irem', '1', 'Side-scrolling', 'Side-scrolling shooter.', 'Rescue humans from the undersea invaders.', 'A unique "pink submarine" shooter by Irem.', 'You must manage your oxygen levels by surfacing or catching fuel, all while shooting aliens and rescuing survivors from the deep.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sqoon-usa', 'NES', 'Sqoon (USA)', '1986', 'Action, Shooter', 'Irem', '1', 'Side-scrolling', 'Side-scrolling shooter.', 'Rescue humans from the undersea invaders.', 'The North American release of the undersea shooter.', 'Famous for its vibrant colors and challenging gameplay that requires both shooting skill and resource management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('square-no-tom-sawyer-japan', 'NES', 'Square no Tom Sawyer (Japan)', '1989', 'Action, Adventure', 'Namco', '1', 'Side-scrolling', 'Turn-based RPG.', 'Experience the adventures of Tom Sawyer in 8-bit.', 'A rare RPG by Square (before Final Fantasy fame).', 'It features a unique art style that looks like a child''s sketches and focuses on the classic Mark Twain story with RPG combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('squashed-usa-proto', 'NES', 'Squashed (USA) (Proto)', '1994', 'Puzzle', 'Open Sesame Games', '1', 'Side-view', 'Puzzle / Action.', 'Survive the crushing walls in this unreleased game.', 'A rare prototype of a game that never made it to market.', 'It features a unique perspective where players must move quickly to avoid being flattened by the environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stack-up-world', 'NES', 'Stack-Up (World)', '1985', 'Accessory', 'Nintendo', '2', 'Static screens', 'Puzzle.', 'Move colored blocks to match the pattern using R.O.B.', 'One of two games designed for the NES Robot.', 'Players use the controller to send commands to R.O.B., who physically moves discs on his base to solve the in-game puzzle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stadium-events-europe', 'NES', 'Stadium Events (Europe)', '1987', 'Sports', 'Fun Factory', '2', 'Side-view', 'Sports / Racing.', 'Win the track and field events using the Power Pad.', 'The ultra-rare precursor to "World Class Track Meet."', 'One of the most expensive games in history. It features four Olympic-style events designed for Nintendo''s floor mat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stadium-events-usa', 'NES', 'Stadium Events (USA)', '1987', 'Sports', 'Fun Factory', '2', 'Side-view', 'Sports / Racing.', 'Win the track and field events using the Power Pad.', 'The rarest licensed North American NES game.', 'Recalled almost immediately to be rebranded as a Nintendo title, making the "Bandai" branded version a legendary collector''s item.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stanley---the-search-for-dr-livingston-usa', 'NES', 'Stanley - The Search for Dr. Livingston (USA)', '1992', 'Action, Platformer', 'Sculptured Software', '1', 'Side-scrolling', 'Side-scrolling action.', 'Find the missing doctor in the heart of Africa.', 'An adventure game with a heavy focus on exploration.', 'Players navigate through jungles and caves, using various tools and weapons to survive the hazards of the 19th-century wilderness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-force-europe', 'NES', 'Star Force (Europe)', '1985', 'Action, Shooter', 'Tecmo', '1', 'Vertical scrolling', 'Vertical shooter.', 'Destroy the floating fortresses of the enemy fleet.', 'A fast-paced arcade shooter by Hudson Soft.', 'Known for its simple but addictive gameplay and the "hidden" bonuses you get by shooting specific background elements.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-force-japan', 'NES', 'Star Force (Japan)', '1985', 'Action, Shooter', 'Tecmo', '1', 'Vertical scrolling', 'Vertical shooter.', 'Destroy the floating fortresses of the enemy fleet.', 'The Famicom port of the Tecmo arcade hit.', 'A legendary title in Japan that helped spark the "shooting game" craze of the mid-80s.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-force-usa', 'NES', 'Star Force (USA)', '1985', 'Action, Shooter', 'Tecmo', '1', 'Vertical scrolling', 'Vertical shooter.', 'Destroy the floating fortresses of the enemy fleet.', 'The North American release of the sci-fi shooter.', 'Players must fly through 24 "areas," each named after a letter of the Greek alphabet, in an endless cosmic war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-gate-japan', 'NES', 'Star Gate (Japan)', '1986', 'Action, Shooter', 'Toho', '1', 'Vertical scrolling', 'Side-scrolling shooter.', 'Protect the humans and destroy the alien landers.', 'The Japanese version of "Defender II."', 'A high-speed, technical shooter where you must monitor a radar to save civilians while fighting off waves of aggressive aliens.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-luster-japan', 'NES', 'Star Luster (Japan)', '1985', 'Action, Shooter', 'HAL Laboratory', '1', 'Top-down', 'Combat Flight Sim.', 'Protect the starbases from the invading fleet.', 'A first-person cockpit shooter by Namco.', 'It blends strategy and action, requiring players to warp between sectors and manage their ship''s energy and shield levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-soldier-japan', 'NES', 'Star Soldier (Japan)', '1986', 'Action, Shooter', 'Hudson Soft', '1', 'Vertical scrolling', 'Vertical shooter.', 'Defeat the Starbrain at the end of each stage.', 'The spiritual successor to Star Force.', 'Famous for its high speed and "caravan" style gameplay, it became a staple of early competitive gaming in Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-soldier-usa', 'NES', 'Star Soldier (USA)', '1989', 'Action, Shooter', 'Hudson Soft', '1', 'Vertical scrolling', 'Shooter / Arcade', 'Defeat enemy waves', 'Vertical space shooter', 'Star Soldier is a fast-paced vertical shooter focused on reflexes, power-ups, and high-score play.');
