INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('startropics-europe', 'NES', 'Startropics (Europe)', '1990', 'Action, Adventure', 'Nintendo', '1', 'Top-down', 'Action / Adventure', 'Explore islands', 'Action-adventure classic', 'Startropics blends exploration, puzzles, and combat in a tropical setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('startropics-usa', 'NES', 'Startropics (USA)', '1990', 'Action, Adventure', 'Nintendo', '1', 'Top-down', 'Action / Adventure', 'Explore islands', 'US version of Startropics', 'The American release maintains the same adventure-focused gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('startropics-2---zodas-revenge-usa', 'NES', 'Startropics 2 - Zoda''s Revenge (USA)', '1994', 'Action, Adventure', 'Nintendo', '1', 'Top-down', 'Action / Adventure', 'Stop Zoda', 'Sequel action-adventure', 'Startropics 2 expands the formula with new abilities, puzzles, and story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stealth-atf-europe', 'NES', 'Stealth ATF (Europe)', '1989', 'Simulation, Flight', 'MicroProse', '1', 'Top-down', 'Combat Flight Sim.', 'Complete stealth missions and destroy enemy targets.', 'A first-person cockpit flight simulator.', 'You pilot a stealth fighter, engaging in dogfights and bombing runs while managing radar and fuel across several global theaters of war.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stealth-atf-usa', 'NES', 'Stealth ATF (USA)', '1989', 'Simulation, Flight', 'MicroProse', '1', 'Top-down', 'Combat Flight Sim.', 'Complete stealth missions and destroy enemy targets.', 'The North American release of the stealth jet sim.', 'It supports up to 2 to 4 players in a competitive dogfight mode, which was quite rare for an 8-bit flight simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sted---iseki-wakusei-no-yabou-japan', 'NES', 'Sted - Iseki Wakusei no Yabou (Japan)', '1988', 'RPG', 'HAL Laboratory', '1', 'Top-down', 'Turn-based RPG.', 'Explore the ruins of a mysterious planet.', 'A sci-fi RPG set in deep space.', 'Known for its atmospheric soundtrack and detailed sprites, it follows a group of explorers uncovering ancient secrets on an alien world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sted---iseki-wakusei-no-yabou-japan-en-by-j2e-v10-~sted---starfield-of-memorable-relics', 'NES', 'Sted - Iseki Wakusei no Yabou (Japan) [En by J2e v1.0] (~Sted - Starfield of Memorable Relics)', '1988', 'RPG', 'HAL Laboratory', '1', 'Top-down', 'Turn-based RPG.', 'Save the galaxy with fully translated English text.', 'The English fan translation of this sci-fi Famicom gem.', 'Essential for understanding the complex plot and equipment management in this "Phantasy Star" style 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sted---iseki-wakusei-no-yabou-japan-en-by-j2e-v10-hack-by-ded302-v10-~sted---starfield-of-memorable-relics-easy-mode', 'NES', 'Sted - Iseki Wakusei no Yabou (Japan) [En by J2e v1.0] [Hack by Ded302 v1.0] (~Sted - Starfield of Memorable Relics) (Easy Mode)', '1988', 'RPG', 'HAL Laboratory', '1', 'Top-down', 'Turn-based RPG.', 'Explore the galaxy with reduced grinding.', 'An "Easy Mode" hack of the translated RPG.', 'It balances the experience and gold gain to make the story flow faster, perfect for players who want to avoid the heavy 80s grind.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sted---iseki-wakusei-no-yabou-japan-en-by-j2e-v10-hack-by-kingmike-v10-~sted---starfield-of-memorable-relics-experience-display', 'NES', 'Sted - Iseki Wakusei no Yabou (Japan) [En by J2e v1.0] [Hack by KingMike v1.0] (~Sted - Starfield of Memorable Relics) (Experience Display)', '1988', 'RPG', 'HAL Laboratory', '1', 'Top-down', 'Turn-based RPG.', 'Explore the galaxy with a fixed UI display.', 'A technical patch for the translated Sted.', 'This specific hack adds a visible Experience Bar or numerical display to better track character progression during battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stick-hunter---exciting-ice-hockey-japan', 'NES', 'Stick Hunter - Exciting Ice Hockey (Japan)', '1988', 'Sports, Ice Hockey', 'Naxat Soft', '2', 'Side-view', 'Sports / Hockey.', 'Win the ice hockey tournament.', 'A fast-paced, top-down ice hockey simulation.', 'It features a "stick" perspective and focuses on arcade-style action, allowing for quick passes and powerful shots on goal.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stinger-usa', 'NES', 'Stinger (USA)', '1988', 'Action, Shooter', 'Seibu Kaihatsu', '1', 'Side-scrolling', 'Side-scrolling shooter.', 'Rescue Dr. Cinnamon and destroy the alien fleet.', 'The Western sequel to "TwinBee."', 'A unique shooter that alternates between horizontal and vertical scrolling stages, featuring the iconic bell power-up system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strange-mario-bros', 'NES', 'Strange Mario Bros.', '1985', 'Action, Platformer', 'Hack', '2', 'Side-scrolling', 'Platformer.', 'Navigate weird levels in this creative hack.', 'A "troll" or "kaizo" style hack of Super Mario Bros.', 'It features invisible blocks, unexpected traps, and surreal level designs intended to challenge even the best Mario players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strategist-asia', 'NES', 'Strategist (Asia)', '1987', 'Strategy', 'Konami', '2', 'Top-down', 'Strategy / Board.', 'Outsmart the opponent on a tactical grid.', 'An unlicensed strategy game by Sachen.', 'Players must capture enemy territory using a set of rules similar to Go or Othello, featuring minimalist 8-bit graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-blaster-ii-pro-unl', 'NES', 'Street Blaster II Pro (Unl)', '1992', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Defeat all fighters to become the champion.', 'An unlicensed fighting game based on Street Fighter.', 'One of many 8-bit "ports" of SFII, attempting to replicate the combos and special moves of the arcade on limited hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-blaster-v-turbo-20-unl', 'NES', 'Street Blaster V Turbo 20 (Unl)', '1993', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Win the world tournament in this pirate fighter.', 'An unlicensed fighter featuring a mix of characters.', 'Often found on multicarts, it''s known for its glitchy but ambitious attempt at 16-bit style fighting mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-cop-usa', 'NES', 'Street Cop (USA)', '1989', 'Action, Beat ''em up', 'Bandai', '1', 'Side-scrolling', 'Action.', 'Pursue and arrest criminals on the city streets.', 'A specialized game for the Power Pad.', 'Players must run in place on the NES floor mat to chase suspects and use the controller to perform arrests and attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-2-pro', 'NES', 'Street Fighter 2 Pro', '1992', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Win the world warrior tournament.', 'Another unlicensed 8-bit port of the Capcom classic.', 'Features a reduced roster of fighters but tries to keep the iconic music and stage backgrounds of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-2010---the-final-fight-usa', 'NES', 'Street Fighter 2010 - The Final Fight (USA)', '1990', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Fight through planets to avenge your partner.', 'A futuristic action game loosely tied to Street Fighter.', 'In the US version, you play as "Ken" from SF in the year 2010, using bionic implants to fight aliens in very difficult levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-2010-japan', 'NES', 'Street Fighter 2010 (Japan)', '1990', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Fight through planets to avenge your partner.', 'The original Japanese version: "2010 Street Fighter."', 'In this version, the protagonist is Kevin, a cyborg cop. The gameplay is identical to the US version: fast, fluid, and extremely hard.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii---the-world-warrior-unl', 'NES', 'Street Fighter II - The World Warrior (Unl)', '1992', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Defeat the 8 world warriors and the grand masters.', 'An unlicensed "bootleg" port of Street Fighter II.', 'This version is famous for how much it actually managed to squeeze onto a Famicom cart, including most of the main cast.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-pro-unl', 'NES', 'Street Fighter II Pro (Unl)', '1992', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Defeat the 8 world warriors and the grand masters.', 'A slightly improved unlicensed version of SFII.', 'Features better color palettes and slightly more responsive controls than earlier 8-bit pirate fighting games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-iii-9-fighter-unl', 'NES', 'Street Fighter III (9 Fighter) (Unl)', '1993', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Battle through a roster of 9 different fighters.', 'An unlicensed 8-bit take on Street Fighter III.', 'While it doesn''t have the "Parry" system, it attempts to replicate the 16-bit sprites and backgrounds of the later arcade entries.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-iv-unl', 'NES', 'Street Fighter IV (Unl)', '1994', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Win the tournament in this modern-styled pirate.', 'An unlicensed game mimicking the SFIV look.', 'A late-era bootleg that uses sprites intended to look like the 3D models of SFIV, but within the constraints of the NES.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-iv:-enhanced-edition', 'NES', 'Street Fighter IV: Enhanced Edition', '1994', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Experience a more polished unlicensed fighter.', 'A fan-hack of the unlicensed SFIV bootleg.', 'This version improves the hit detection and cleans up the graphics, making it one of the more "playable" 8-bit pirate fighters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-v-20-peoples-unl', 'NES', 'Street Fighter V (20 Peoples) (Unl)', '1995', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Choose from a massive (duplicated) roster to fight.', 'A pirate fighter with a "fake" high character count.', 'Like many bootlegs, it repeats the same characters with different colors to fill up a 20-slot selection screen.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-zero-2-97-unl', 'NES', 'Street Fighter Zero 2 ''97 (Unl)', '1997', 'Action, Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Experience the "Alpha" series on your NES.', 'An unlicensed port of Street Fighter Alpha 2.', 'It features the "chibi" or younger looks of the characters and tries to include some of the Super Combo mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-gangs-europe', 'NES', 'Street Gangs (Europe)', '1989', 'Action, Beat ''em up', 'Atlus', '2', 'Side-scrolling', 'Beat ''em up / RPG.', 'Rescue your girlfriend and clean up the city.', 'The European name for "River City Ransom."', 'Two high schoolers fight through gangs, eating at restaurants and buying items to boost their stats in this cult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-heroes-asia-unl', 'NES', 'Street Heroes (Asia) (Unl)', '1992', 'Action, Beat ''em up', 'Unknown', '2', 'Side-scrolling', 'Fighting.', 'Defeat rivals in this unlicensed brawler.', 'A unique unlicensed fighting game by Sachen.', 'Features original characters and its own fighting engine, separate from the many Street Fighter clones of the era.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strider-usa', 'NES', 'Strider (USA)', '1989', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Infiltrate the Kazakh Soviet Socialist Republic.', 'An action-adventure different from the arcade version.', 'Unlike the arcade''s linear path, this NES version is more of a "Metroidvania" where you must find floppy disks to unlock new areas.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('study-box-japan', 'NES', 'Study Box (Japan)', '1989', 'Educational', 'Nintendo', '1', 'Static screens', 'Educational.', 'Learn various subjects using the Study Box add-on.', 'A specialized educational peripheral for Famicom.', 'It used a cassette-tape based system to provide audio instructions alongside the 8-bit graphics for school lessons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('stunt-kids-usa-unl', 'NES', 'Stunt Kids (USA) (Unl)', '1992', 'Action, Platformer', 'Unknown', '1', 'Side-scrolling', 'Racing / Action.', 'Complete stunt courses without crashing.', 'An unlicensed game by Codemasters.', 'Players drive buggies through obstacle-filled tracks, focusing on jumps and speed to beat the clock in this "Quattro" series title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sugoro-quest---dice-no-senshitachi-japan', 'NES', 'Sugoro Quest - Dice no Senshitachi (Japan)', '1991', 'RPG', 'Victor Interactive', '1', 'Top-down', 'RPG / Board Game.', 'Defeat the monsters using a dice-based battle system.', 'A unique hybrid of a board game and a JRPG.', 'Players move across a map like a board game, but enter turn-based battles where dice rolls determine the strength of your attacks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sugoro-quest---dice-no-senshitachi-japan-en-by-alanmidas-v20070221-fix-by-kingmike-~sugoro-quest---the-quest-of-dice-heroes', 'NES', 'Sugoro Quest - Dice no Senshitachi (Japan) [En by AlanMidas v20070221] [Fix by KingMike] (~Sugoro Quest - The Quest of Dice Heroes)', '1991', 'RPG', 'Victor Interactive', '1', 'Top-down', 'RPG / Board Game.', 'Conquer the quest with fully translated text.', 'The English fan translation of the Famicom original.', 'This patch is crucial to understand the dice mechanics and the different "Gods" you can summon to help you in battle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('suikoden---tenmei-no-chikai-japan', 'NES', 'Suikoden - Tenmei no Chikai (Japan)', '1992', 'RPG', 'Koei', '1', 'Top-down', 'Strategy / Sim.', 'Unify China as a leader of the 108 outlaws.', 'Based on the classic Chinese novel "Water Margin."', 'A deep strategy game by Koei where you manage a band of heroes, focusing on tactical warfare and province management.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sukeban-deka-3-japan', 'NES', 'Sukeban Deka 3 (Japan)', '1989', 'Action, Adventure', 'Toei Animation', '1', 'Side-scrolling', 'Side-scrolling action.', 'Stop the criminal conspiracy as a yo-yo wielding girl.', 'Based on the famous "Delinquent Girl Detective" series.', 'You control a high school girl who uses a metal yo-yo as a weapon to fight through waves of thugs and bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summer-carnival-92---recca-japan', 'NES', 'Summer Carnival ''92 - Recca (Japan)', '1992', 'Action, Shooter', 'Naxat Soft', '1', 'Vertical scrolling', 'Vertical shooter.', 'Survive the most intense bullet hell on the NES.', 'A technical masterpiece developed for a tournament.', 'It features a staggering amount of sprites without slowdown, making it one of the fastest and most difficult shooters ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summer-carnival-92---recca-japan-en-by-aeon-genesis-v10-~raging-fire---recca', 'NES', 'Summer Carnival ''92 - Recca (Japan) [En by Aeon Genesis v1.0] (~Raging Fire - Recca)', '1992', 'Action, Shooter', 'Naxat Soft', '1', 'Vertical scrolling', 'Vertical shooter.', 'Experience the Recca tournament in English.', 'The fan translation of Summer Carnival ''92.', 'While it’s a shooter, the translation helps navigate the menus and the "Sound Test" mode of this 8-bit engineering marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summer-carnival-92---recca-japan-hack-by-sliver-x-v10-~recca---pure', 'NES', 'Summer Carnival ''92 - Recca (Japan) [Hack by Sliver X v1.0] (~Recca - Pure)', '1992', 'Action, Shooter', 'Naxat Soft', '1', 'Vertical scrolling', 'Shooter / Arcade', 'Survive and score high', 'Pure arcade shooter hack', 'Recca - Pure is a modified version of Summer Carnival ''92 that removes scoring restrictions to focus on raw shooting skill.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sunday-funday---the-ride-usa-unl', 'NES', 'Sunday Funday - The Ride (USA) (Unl)', '1993', 'Action, Platformer', 'Wisdom Tree', '1', 'Side-scrolling', 'Action / Arcade', 'Complete the ride', 'Action platform game', 'Sunday Funday - The Ride is an unlicensed action game featuring simple stages and arcade-style challenges.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sunman-europe-proto', 'NES', 'Sunman (Europe) (Proto)', '1992', 'Action, Platformer', 'Sunsoft', '1', 'Side-scrolling', 'Action / Platformer', 'Complete stages', 'Unreleased superhero prototype', 'Sunman is a prototype platformer starring a superhero inspired by comic book themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-arabian-japan', 'NES', 'Super Arabian (Japan)', '1985', 'Action, Platformer', 'Sunsoft', '1', 'Side-scrolling', 'Action / Platformer', 'Rescue captives', 'Classic platform action', 'Super Arabian is an arcade-style platformer focused on jumping, enemies, and rescue objectives.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-black-onyx-japan', 'NES', 'Super Black Onyx (Japan)', '1988', 'RPG', 'Bullet-Proof Software', '1', 'Top-down', 'RPG / Adventure', 'Explore and survive', 'Early fantasy RPG', 'Super Black Onyx is a pioneering Japanese RPG with dungeon exploration and turn-based combat.');
