INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-japan', 'NES', 'Super Chinese (Japan)', '1986', 'Action, Beat ''em up', 'Culture Brain', '2', 'Side-scrolling', 'Action / Beat ''em up', 'Defeat enemies', 'Classic Kunio-style brawler', 'Super Chinese is a side-scrolling beat ''em up featuring martial arts combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-2---dragon-kid-japan', 'NES', 'Super Chinese 2 - Dragon Kid (Japan)', '1989', 'Action, Beat ''em up', 'Culture Brain', '2', 'Side-scrolling', 'Action / Beat ''em up', 'Defeat enemies', 'Brawler sequel', 'Super Chinese 2 expands the original with more moves, stages, and improved mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-chinese-3-japan', 'NES', 'Super Chinese 3 (Japan)', '1990', 'Action, Beat ''em up', 'Culture Brain', '2', 'Side-scrolling', 'Action / RPG.', 'Save the Chinaland kingdom from the alien invasion.', 'The third entry in the "Ninja Boy" series.', 'It blends top-down RPG exploration with side-scrolling action combat. It features a high level of polish and cooperative gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-contra-japan', 'NES', 'Super Contra (Japan)', '1990', 'Action, Shooter', 'Konami', '2', 'Side-scrolling', 'Run and gun.', 'Destroy the alien life forms and their bases.', 'The original Famicom version of the arcade sequel.', 'Known as "Super C" in the West, this version features more frames of animation and a slightly different difficulty balance than the NES port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-contra-ii', 'NES', 'Super Contra II', '1990', 'Action, Shooter', 'Unlicensed', '2', 'Side-scrolling', 'Run and gun.', 'Stop the alien threat in this unlicensed sequel.', 'An unlicensed/pirate sequel to the Contra series.', 'Often a hack of the original games or a completely new (but glitchy) build, it tries to capture the intense 8-bit military action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dodge-ball-usa', 'NES', 'Super Dodge Ball (USA)', '1989', 'Sports, Dodgeball', 'Tecmo', '2', 'Side-view', 'Sports / Fighting.', 'Defeat international teams in a lethal dodgeball tour.', 'A cult classic sports game by Technos.', 'Part of the Kunio-kun series, it features "super shots" that can blast opponents out of the arena, blending sports with combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dodge-ball-usa-hack-by-aka-v10-4-player-edition', 'NES', 'Super Dodge Ball (USA) [Hack by Aka v1.0] (4 Player Edition)', '1989', 'Sports, Dodgeball', 'Tecmo', '4', 'Side-view', 'Sports / Fighting.', 'Play dodgeball with up to 4 players simultaneously.', 'A technical hack of the original Super Dodge Ball.', 'This version enables 4-player support, making the bean-ball battles even more chaotic and fun for local multiplayer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-donkey-kong-unl', 'NES', 'Super Donkey Kong (Unl)', '1994', 'Action, Platformer', 'Unlicensed', '1', 'Side-scrolling', 'Platformer.', 'Rescue the bananas in this unlicensed port.', 'An 8-bit unlicensed version of Donkey Kong Country.', 'A technical marvel for the NES, it attempts to recreate the pre-rendered 16-bit graphics and levels of the SNES classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-dynamix-badminton-japan', 'NES', 'Super Dyna''mix Badminton (Japan)', '1989', 'Sports, Badminton', 'Metro', '2', 'Side-view', 'Sports / Badminton.', 'Win the world badminton championship.', 'A realistic and fast-paced badminton simulation.', 'It features deep mechanics for smashes and drops, requiring precise timing and positioning to defeat the international AI.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-glove-ball-usa', 'NES', 'Super Glove Ball (USA)', '1990', 'Sports, Baseball', 'Rare', '2', 'Side-view', 'Puzzle / Action.', 'Navigate through a 3D maze to find the exit.', 'A game specifically designed for the Power Glove.', 'Players use hand gestures to swat a ball and hit targets in a virtual room, attempting to prove the glove''s precision.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-jeopardy!-usa', 'NES', 'Super Jeopardy! (USA)', '1991', 'Trivia', 'GameTek', '3', 'Static screens', 'Quiz / Board Game.', 'Win the grand prize by answering in the form of a question.', 'A high-stakes version of the classic TV show.', 'Based on the "Super Jeopardy!" tournament, it features 4-player support and thousands of challenging trivia questions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-kaizo-bros', 'NES', 'Super Kaizo Bros.', '2012', 'Action, Platformer', 'Hack', '1', 'Side-scrolling', 'Platformer.', 'Survive the most punishing Mario levels ever made.', 'An extreme difficulty hack of Super Mario Bros.', 'Designed to be "unfair," it requires frame-perfect jumps and knowledge of hidden traps that kill the player instantly.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-bros-2', 'NES', 'Super Luigi Bros. 2', '2015', 'Action, Platformer', 'Hack', '1', 'Side-scrolling', 'Platformer.', 'Save the Dream World as the green brother.', 'A hack of SMB2 featuring Luigi as the lead.', 'It swaps Mario for Luigi, often adjusting the jump height and physics to better represent Luigi''s unique abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-bros-3-35th-anniversary', 'NES', 'Super Luigi Bros. 3 (35th Anniversary)', '2020', 'Action, Platformer', 'Hack', '1', 'Side-scrolling', 'Platformer.', 'Embark on a grand quest to celebrate the anniversary.', 'A celebratory hack of the legendary SMB3.', 'Features custom palettes and Luigi-centric level adjustments to honor the 35th anniversary of the franchise.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-bros-by-l___e___t', 'NES', 'Super Luigi Bros. by L___E___T', '2013', 'Action, Platformer', 'Hack', '1', 'Side-scrolling', 'Platformer.', 'Rescue the Princess in this Luigi-themed overhaul.', 'A total conversion hack of Super Mario Bros.', 'Every sprite and many level elements are changed to put Luigi in the spotlight, created by a well-known community hacker.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-bros-by-thehappyfaceking', 'NES', 'Super Luigi Bros. by TheHappyFaceKing', '2014', 'Action, Platformer', 'Hack', '1', 'Side-scrolling', 'Platformer.', 'Experience the Mushroom Kingdom as Luigi.', 'Another creative "Green Mario" conversion.', 'It focuses on aesthetic changes, giving the classic 1985 game a fresh look centered around Mario''s younger brother.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-luigi-bros-by-thenintendude64', 'NES', 'Super Luigi Bros. by TheNintendude64', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Clear the classic stages with Luigi''s physics.', 'A physics-focused hack of the first Mario game.', 'Adjusts the traction and jump height to feel more like the "slippery" Luigi from later entries in the series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-&-sonic-2-unl', 'NES', 'Super Mario & Sonic 2 (Unl)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Navigate levels featuring both mascot icons.', 'A bizarre unlicensed crossover bootleg.', 'It places Sonic or Mario in worlds that blend elements from both SEGA and Nintendo, often using assets from various 8-bit games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-all-stars-nes', 'NES', 'Super Mario All Stars NES', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Play the SNES collection on 8-bit hardware.', 'A "demake" hack attempting to bring All-Stars to NES.', 'It updates the graphics of the original NES games to look more like the 16-bit remakes, including a level selection menu.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros---another-adventure-201', 'NES', 'Super Mario Bros - Another Adventure 2.01', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Explore an entirely new set of Mario levels.', 'A high-quality level hack of the original SMB.', 'It features creative level design that feels like an official "lost" sequel, with increased difficulty and new secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-health-bar', 'NES', 'Super Mario Bros Health Bar', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Survive more than one hit in the Mushroom Kingdom.', 'A mechanical hack adding a life meter to Mario.', 'Instead of dying instantly, Mario has a health bar, allowing for a more forgiving (but still challenging) platforming experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros---all-star-levels', 'NES', 'Super Mario Bros. - All Star Levels', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Play the All-Stars versions of the classic maps.', 'A graphical hack focused on the SNES aesthetic.', 'It brings the refined tilesets and background art from the SNES version back to the original 8-bit engine.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros---mario-vs-airman-airman-stage-only', 'NES', 'Super Mario Bros. - Mario Vs. Airman (Airman Stage Only)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer.', 'Defeat Airman in a Mega Man crossover level.', 'A famous "crossover" hack of SMB.', 'Mario enters the world of Mega Man 2 to face the infamous Airman, blending the physics of Mario with the combat of Mega Man.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros---mario-vs-airman-mushroom-kingdom-added', 'NES', 'Super Mario Bros. - Mario Vs. Airman (Mushroom Kingdom Added)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer.', 'Explore the Mushroom Kingdom before fighting Airman.', 'An expanded version of the Airman crossover.', 'It adds a traditional Mario-style level leading up to the climactic battle against the Mega Man boss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros---peach-&-daisy', 'NES', 'Super Mario Bros. - Peach & Daisy', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Save the kingdom as the Princesses.', 'A character-swap hack of the original Mario game.', 'Replaces Mario and Luigi with Peach and Daisy, featuring custom sprites and animations for the female leads.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-13-unl', 'NES', 'Super Mario Bros. 13 (Unl)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Navigate weird levels in this unlicensed sequel.', 'An unlicensed Chinese pirate game.', 'Often a hack of a completely different game (like Saiyuuki World), rebranded as a "new" Mario title for clones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-17-unl', 'NES', 'Super Mario Bros. 17 (Unl)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Defeat enemies in this bizarre bootleg.', 'Another entry in the infamous "numbered" pirate series.', 'Usually a hack of Circus Charlie or another arcade game, edited to feature Mario sprites and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-3-crowned-edition', 'NES', 'Super Mario Bros. 3 Crowned Edition', '1988', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Play the 3rd adventure with the "Super Crown" item.', 'A modern hack inspired by the "Bowsette" meme.', 'Introduces the crown power-up that transforms enemies and provides Mario with new, fan-inspired abilities.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-3-crowned-koopapeach', 'NES', 'Super Mario Bros. 3 Crowned-KoopaPeach', '1988', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Face a "crowned" version of Peach and Bowser.', 'A specific aesthetic hack of SMB3.', 'It replaces the final bosses and some NPCs with "Peachified" versions, following the popular internet subculture themes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-3+-beta-10', 'NES', 'Super Mario Bros. 3+ Beta 1.0', '1988', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Experience an "enhanced" version of SMB3.', 'A massive "Quality of Life" and expansion hack.', 'It adds features like a save system, character swapping on the fly, and restored content that was cut from the original game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-5000', 'NES', 'Super Mario Bros. 5000', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Clear thousands of (randomized) levels.', 'A massive level-compilation hack.', 'It features a huge number of modified stages, ranging from extremely easy to "Kaizo" difficulty, designed for endless play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-6-v11-english', 'NES', 'Super Mario Bros. 6 (v1.1) (English)', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Save the princess in this English-translated pirate.', 'An unlicensed port of "Tiny Toon Adventures."', 'One of the most famous bootlegs where Buster Bunny is replaced by Mario, making for a surprisingly high-quality (but fake) Mario game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-8-english', 'NES', 'Super Mario Bros. 8 English', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Navigate the "Don Gohan" world as Mario.', 'An unlicensed hack of the game "Don Doko Don 2."', 'It replaces the hammer-wielding dwarves with Mario, creating a very polished and fun "unofficial" Mario platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-8-sb-edition', 'NES', 'Super Mario Bros. 8 S.B. Edition', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Mario hack variant', 'Super Mario Bros. 8 S.B. Edition is a modified version of the original game featuring gameplay tweaks and custom changes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-8-spanish', 'NES', 'Super Mario Bros. 8 Spanish', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Spanish Mario hack', 'Super Mario Bros. 8 Spanish is a fan-made Mario hack with Spanish-language elements and modified levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-chaos-control', 'NES', 'Super Mario Bros. Chaos Control', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Control-focused Mario hack', 'Super Mario Bros. Chaos Control alters Mario physics and enemy behavior for a different challenge.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-co-op-christmas-edition-13', 'NES', 'Super Mario Bros. CO OP Christmas Edition 1.3', '1985', 'Action, Platformer', 'Nintendo', '2', 'Side-scrolling', 'Action / Platformer', 'Finish levels together', 'Co-op holiday hack', 'Super Mario Bros. CO OP Christmas Edition 1.3 adds cooperative play and festive-themed changes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-new', 'NES', 'Super Mario Bros. NEW', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Modified Mario experience', 'Super Mario Bros. NEW is a hack that refreshes visuals and level layouts while keeping core gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-resprited', 'NES', 'Super Mario Bros. Resprited', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Visual overhaul hack', 'Super Mario Bros. Resprited replaces character and environment sprites with new artwork.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-tweaked', 'NES', 'Super Mario Bros. Tweaked', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Clear stages', 'Gameplay balance hack', 'Super Mario Bros. Tweaked subtly adjusts physics, enemy placement, and difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros-two-player-hack-shared-lives', 'NES', 'Super Mario Bros. Two-Player Hack (Shared Lives)', '1985', 'Action, Platformer', 'Nintendo', '2', 'Side-scrolling', 'Action / Platformer', 'Survive together', 'Shared-life co-op hack', 'Super Mario Bros. Two-Player Hack allows two players to share lives during cooperative play.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-bros:-peach-edition', 'NES', 'Super Mario Bros.: Peach Edition', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Action / Platformer', 'Rescue Mario-themed world', 'Peach-focused hack', 'Super Mario Bros.: Peach Edition stars Princess Peach as the playable character with altered mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-co-op-coin-challenge-11', 'NES', 'Super Mario Co-Op Coin Challenge 1.1', '1985', 'Action, Platformer', 'Nintendo', '2', 'Side-scrolling', 'Action / Platformer', 'Collect coins cooperatively', 'Coin-focused co-op challenge', 'Super Mario Co-Op Coin Challenge 1.1 emphasizes cooperative coin collection over traditional progression.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-co-op-coin-challenge-11-shared-lives', 'NES', 'Super Mario Co-Op Coin Challenge 1.1 (Shared Lives)', '1985', 'Action, Platformer', 'Nintendo', '2', 'Side-scrolling', 'Action / Platformer', 'Collect coins cooperatively', 'Shared-life co-op variant', 'This version of the Coin Challenge adds shared lives to increase teamwork.');
