INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pang-ii-asia-unl', 'NES', 'Super Pang II (Asia) (Unl)', '1992', 'Action', 'Mitchell', '2', 'Arcade-style', 'Action / Arcade', 'Defeat enemies', 'Expanded bubble shooter', 'Super Pang II builds on the original with increased difficulty and additional stages.');
