INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pitfall-japan', 'NES', 'Super Pitfall (Japan)', '1986', 'Action, Platformer', 'Activision', '1', 'Side-scrolling', 'Action / Platformer', 'Explore and survive', 'Difficult platform adventure', 'Super Pitfall is a non-linear exploration platformer known for its high difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pitfall-usa', 'NES', 'Super Pitfall (USA)', '1986', 'Action, Platformer', 'Activision', '1', 'Side-scrolling', 'Action / Platformer', 'Explore and survive', 'Western release version', 'The USA version of Super Pitfall retains the same exploration-heavy design with minimal guidance.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pitfall-30th-anniversary-edition-english', 'NES', 'Super Pitfall 30th Anniversary Edition (English)', '1986', 'Action, Platformer', 'Activision', '1', 'Side-scrolling', 'Action / Adventure.', 'Rescue your family and find the Raj Diamond.', 'A massive overhaul of the original game.', 'This 30th-anniversary hack fixes the glitches, improves the graphics, and balances the gameplay, turning a "bad" game into a masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pitfall-30th-anniversary-edition-portuguese', 'NES', 'Super Pitfall 30th Anniversary Edition (Portuguese)', '1986', 'Action, Platformer', 'Activision', '1', 'Side-scrolling', 'Action / Adventure.', 'Rescue your family with Portuguese text.', 'The Portuguese localized version of the 30th hack.', 'All menus and hints are translated, allowing Portuguese-speaking fans to enjoy this vastly improved version of Harry''s adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-pitfall-ii-localization-prototype', 'NES', 'Super Pitfall II (Localization Prototype)', '1986', 'Action, Platformer', 'Activision', '1', 'Side-scrolling', 'Action / Platformer.', 'Navigate the lost caverns in this prototype.', 'A localization prototype of "Atlantis no Nazo."', 'Originally intended to be the sequel to Pitfall, it''s a fast-paced platformer with branching paths and secret rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-princess-peach-3', 'NES', 'Super Princess Peach 3', '1985', 'Action, Platformer', 'Nintendo', '1', 'Side-scrolling', 'Platformer.', 'Save the kingdom as Peach in this unlicensed sequel.', 'An unlicensed hack of another platformer featuring Peach.', 'It uses sprites from various games to give Peach a solo adventure long before her official Nintendo DS debut.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-princess-sis---two-drunk-princess-two-players-hack-10', 'NES', 'Super Princess Sis - Two Drunk Princess (Two Players Hack) 1.0', '1985', 'Action, Platformer', 'Nintendo', '2', 'Side-scrolling', 'Platformer / Hack.', 'Navigate levels in this humorous 2-player hack.', 'A funny and chaotic modification of SMB.', 'It features two "drunk" princesses with altered physics and funny animations, designed for a hilarious local co-op experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-real-baseball-88-japan', 'NES', 'Super Real Baseball ''88 (Japan)', '1988', 'Sports', 'Namco', '2', 'Simulation', 'Sports / Baseball.', 'Win the 1988 pro baseball season.', 'A realistic baseball sim with large character models.', 'It focuses on a more "simulation" feel with detailed pitching mechanics and rosters based on the 1988 Japanese league.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-rugby-japan', 'NES', 'Super Rugby (Japan)', '1989', 'Sports', 'Tonkin House', '2', 'Side view', 'Sports / Rugby.', 'Lead your team to victory in the rugby world tour.', 'One of the few rugby simulations for the Famicom.', 'It features strategic gameplay where you manage scrums, passes, and kicks in a top-down view of the field.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonic', 'NES', 'Super Sonic', '1991', 'Action, Platformer', 'Sega (Hack)', '1', 'Side-scrolling', 'Platformer.', 'Race through levels as the blue hedgehog.', 'An unlicensed 8-bit port of Sonic the Hedgehog.', 'An ambitious bootleg that tries to replicate Sonic''s speed and loop-de-loops using the NES hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonic-bros', 'NES', 'Super Sonic Bros', '1991', 'Action, Platformer', 'Sega (Hack)', '1', 'Side-scrolling', 'Platformer.', 'Explore the world in a Sonic and Mario mashup.', 'A creative hack blending the two icons.', 'Usually a hack of SMB that replaces Mario with Sonic, adjusting the physics to make the gameplay feel faster.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sonic-bros-2', 'NES', 'Super Sonic Bros 2', '1991', 'Action, Platformer', 'Sega (Hack)', '1', 'Side-scrolling', 'Platformer.', 'Tackle new levels in this mascot crossover sequel.', 'A follow-up to the Sonic/Mario hybrid bootleg.', 'It features more polished sprites and modified levels from various games to create a unique 8-bit "dream match."');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spike-vball-europe', 'NES', 'Super Spike V''Ball (Europe)', '1988', 'Sports, Volleyball', 'Nintendo', '2', 'Side view', 'Sports / Volleyball.', 'Win the beach volleyball tournament.', 'A high-energy, arcade-style volleyball game.', 'Players can perform "Super Spikes" and powerful blocks, featuring varied teams and locations like Hawaii and New York.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spike-vball-usa', 'NES', 'Super Spike V''Ball (USA)', '1988', 'Sports, Volleyball', 'Nintendo', '2', 'Side view', 'Sports / Volleyball.', 'Win the beach volleyball tournament.', 'The definitive North American release of the hit.', 'Known for its tight controls and fun 2-player mode, it’s one of the best sports games on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spike-vball-+-nintendo-world-cup-usa', 'NES', 'Super Spike V''Ball + Nintendo World Cup (USA)', '1990', 'Sports', 'Nintendo', '4', 'Arcade-style', 'Sports / Comp.', 'Win in both Volleyball and Soccer.', 'A 2-in-1 cartridge often bundled with the NES.', 'A classic duo that provided hours of sports action, featuring both Super Spike V''Ball and the frantic Nintendo World Cup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sports-challenge-europe-unl', 'NES', 'Super Sports Challenge (Europe) (Unl)', '1990', 'Sports', 'Unknown', '2', 'Arcade-style', 'Sports / Multi.', 'Compete in 3 different sports events.', 'An unlicensed compilation by Codemasters.', 'Includes simplified versions of various sports, focusing on high-score chasing and simple arcade mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sports-challenge-europe-unl-plug-thru-cart', 'NES', 'Super Sports Challenge (Europe) (Unl) (Plug-Thru Cart)', '1990', 'Sports', 'Unknown', '2', 'Arcade-style', 'Sports / Multi.', 'Use the "Plug-Thru" technology to play.', 'A specific version of the Codemasters collection.', 'These carts allowed another game to be plugged on top, a unique hardware workaround for unlicensed titles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sprint-japan', 'NES', 'Super Sprint (Japan)', '1989', 'Racing', 'Atari Games', '2', 'Top-down', 'Racing.', 'Win the circuit races and upgrade your car.', 'A top-down arcade racing classic.', 'Players race mini cars on twisty tracks, collecting wrenches to upgrade acceleration, tires, and top speed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-sprint-usa-unl', 'NES', 'Super Sprint (USA) (Unl)', '1989', 'Racing', 'Atari Games', '2', 'Top-down', 'Racing.', 'Win the circuit races and upgrade your car.', 'The unlicensed US version by Tengen.', 'A perfectly faithful port of the arcade original, best played with multiple people for chaotic 8-bit racing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spy-hunter-europe', 'NES', 'Super Spy Hunter (Europe)', '1990', 'Action', 'Sunsoft', '1', 'Top-down', 'Combat Racing.', 'Stop the terrorists with your high-tech vehicle.', 'A massive sequel known as "Battle Formula."', 'One of the most technically impressive games on NES, featuring transforming vehicles and incredible parallax scrolling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-spy-hunter-usa', 'NES', 'Super Spy Hunter (USA)', '1990', 'Action', 'Sunsoft', '1', 'Top-down', 'Combat Racing.', 'Stop the terrorists with your high-tech vehicle.', 'The North American version of Battle Formula.', 'It significantly improves on the original Spy Hunter with more action, boss fights, and varied level designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-star-force-japan', 'NES', 'Super Star Force (Japan)', '1990', 'Shoot ''em up', 'Toaplan', '1', 'Vertical scrolling', 'Vertical shooter / RPG.', 'Travel through time to defeat the alien fleet.', 'A unique hybrid of a shooter and an adventure game.', 'Between shooting stages, players explore planets on foot to find clues and items, making it much deeper than the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-team-games-usa', 'NES', 'Super Team Games (USA)', '1992', 'Sports', 'Interplay', '4', 'Mini-game collection', 'Sports / Mini.', 'Win the obstacle course using the Power Pad.', 'A collection of events designed for the floor mat.', 'Features activities like water crossing and bubble jumping, requiring physical movement to control the on-screen action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-turrican-europe', 'NES', 'Super Turrican (Europe)', '1993', 'Action, Platformer', 'Factor 5', '1', 'Side-scrolling', 'Side-scrolling action.', 'Save the galaxy from the "Machine" empire.', 'A polished 8-bit version of the European classic.', 'Known for its incredible music and the "freeze" beam weapon, it offers large, explorable levels and intense combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-utau-three-sisters-feat-namine-ritsu', 'NES', 'Super UTAU Three Sisters (feat. Namine Ritsu)', '2019', 'Music, Rhythm', 'Homebrew', '1', 'Experimental', 'Music / Hack.', 'Enjoy this custom music-themed modification.', 'A fan-made hack featuring UTAU vocaloid characters.', 'It replaces game assets with Namine Ritsu and other virtual singers, creating a unique "idol" themed experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-utau-three-sisters-feat-namine-ritsu', 'NES', 'Super UTAU Three Sisters (feat. Namine Ritsu)', '2019', 'Music, Rhythm', 'Homebrew', '1', 'Experimental', 'Vertical shooter.', 'Solve the mystery of Gump in this expanded sequel.', 'An improved version of the legendary Xevious.', 'It adds more enemy types and hidden secrets, requiring players to hit specific background spots to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-xevious---gump-no-nazo-japan', 'NES', 'Super Xevious - Gump no Nazo (Japan)', '1986', 'Shoot ''em up', 'Namco', '1', 'Vertical scrolling', 'Side-scrolling action.', 'Protect Metropolis from Lex Luthor.', 'A unique Japanese take on the Man of Steel.', 'It features a "chibi" Superman and focuses on using different powers to navigate city and underground levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman-japan', 'NES', 'Superman (Japan)', '1987', 'Action, Adventure', 'Kotobuki Systems', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect Metropolis from Lex Luthor.', 'The North American release by Kemco.', 'Superman must change in phone booths to use his powers, fighting classic villains in this challenging action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman-usa', 'NES', 'Superman (USA)', '1987', 'Action, Adventure', 'Kotobuki Systems', '1', 'Side-scrolling', 'Side-scrolling action.', 'Experience an improved version of the quest.', 'A fan-hack of the original NES Superman.', 'It fixes various bugs and improves the sprite work to make the game more faithful to the comics and movies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman-2---specter-edition', 'NES', 'Superman 2 - Specter Edition', '1992', 'Action', 'Homebrew', '1', 'Side-scrolling', 'Sports / Wrestling.', 'Win the world championship belt.', 'A professional wrestling sim by Nihon Bussan.', 'It features a deep roster and a variety of moves, focusing on the spectacle and drama of Japanese pro wrestling.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superstar-pro-wrestling-japan', 'NES', 'Superstar Pro Wrestling (Japan)', '1989', 'Sports, Wrestling', 'Technōs Japan', '2', 'Side view', 'Side-scrolling action.', 'Protect the environment and defeat Arcane.', 'A platformer based on the animated series.', 'Swamp Thing uses his elemental powers to fight through swamps and labs in a quest to stop ecological destruction.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('swamp-thing-europe', 'NES', 'Swamp Thing (Europe)', '1992', 'Action, Platformer', 'Imagineering', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect the environment and defeat Arcane.', 'The North American release of the eco-action game.', 'Features colorful graphics and a variety of power-ups that allow the hero to transform his limbs into weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('swamp-thing-usa', 'NES', 'Swamp Thing (USA)', '1992', 'Action, Platformer', 'Imagineering', '1', 'Side-scrolling', 'Strategy / Action.', 'Lead a tactical team to rescue hostages.', 'A unique police strategy game.', 'Players manage a squad, planning breaches and choosing the right equipment to neutralize criminals in various scenarios.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('swat---special-weapons-and-tactics-japan', 'NES', 'SWAT - Special Weapons and Tactics (Japan)', '1990', 'Action', 'Tose', '1', 'Top-down', 'RPG / Horror.', 'Escape the haunted Mamiya manor alive.', 'The precursor to the Resident Evil series.', 'A masterpiece of horror where you manage 5 characters with unique items. If a character dies, they stay dead. Extremely atmospheric.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sweet-home-japan', 'NES', 'Sweet Home (Japan)', '1989', 'Horror, RPG', 'Capcom', '1', 'Top-down', 'RPG / Horror.', 'Explore the manor in this early build.', 'A rare development prototype of the horror hit.', 'It contains slightly different puzzles and early versions of the terrifying ghost encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sweet-home-japan-beta', 'NES', 'Sweet Home (Japan) (Beta)', '1989', 'Horror, RPG', 'Capcom', '1', 'Top-down', 'RPG / Horror.', 'Escape the manor with fully translated text.', 'The legendary English fan translation.', 'Absolutely essential to play this game. It translates the deep lore, clues, and tragic story of the haunted mansion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sweet-home-japan-en-by-gaijin+suicidal-v10', 'NES', 'Sweet Home (Japan) [En by Gaijin+Suicidal v1.0]', '1989', 'Horror, RPG', 'Capcom', '1', 'Top-down', 'Side-scrolling action.', 'Defeat the evil wizard and save the kingdom.', 'A high-quality action game with large sprites.', 'Known for its challenging combat and beautiful backgrounds, it focuses on strategic sword fighting and magic use.');
