INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bouken-jima-japan', 'NES', 'Takahashi Meijin no Bouken Jima (Japan)', '1986', 'Action, Platformer', 'Hudson Soft', '1', 'Side-scrolling', 'Action / Platformer', 'Survive islands', 'Classic action platformer', 'Takahashi Meijin no Bouken Jima stars an adventurer navigating dangerous islands filled with enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bouken-jima-ii-japan', 'NES', 'Takahashi Meijin no Bouken Jima II (Japan)', '1988', 'Action, Platformer', 'Hudson Soft', '1', 'Side-scrolling', 'Action / Platformer', 'Survive islands', 'Expanded sequel', 'Bouken Jima II builds upon the original with larger levels and increased difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bouken-jima-iii-japan', 'NES', 'Takahashi Meijin no Bouken Jima III (Japan)', '1991', 'Action, Platformer', 'Hudson Soft', '1', 'Side-scrolling', 'Platformer.', 'Rescue Higgins'' girlfriend from the aliens.', 'The third tropical adventure of Master Higgins.', 'It introduces more dinosaur companions and refined mechanics, including a password system to keep your inventory of weapons and mounts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bouken-jima-iv-japan', 'NES', 'Takahashi Meijin no Bouken Jima IV (Japan)', '1994', 'Action, Platformer', 'Hudson Soft', '1', 'Side-scrolling', 'Action / Adventure.', 'Rescue the dinosaur friends from the evil eggplant.', 'The final official Famicom game ever released.', 'Unlike the linear previous entries, this is a "Metroidvania" with a large map, new tools, and a focus on exploration and backtracking.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bouken-jima-iv-japan-en-by-demiforce-v10-~adventure-island-iv', 'NES', 'Takahashi Meijin no Bouken Jima IV (Japan) [En by Demiforce v1.0] (~Adventure Island IV)', '1994', 'Action, Platformer', 'Hudson Soft', '1', 'Side-scrolling', 'Action / Adventure.', 'Save the dinosaurs with fully translated text.', 'The English fan translation of the final Famicom title.', 'Essential for understanding the item descriptions and clues needed to navigate the non-linear world of Higgins'' last 8-bit quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takahashi-meijin-no-bugutte-honey-japan', 'NES', 'Takahashi Meijin no Bugutte Honey (Japan)', '1991', 'Action, Puzzle', 'Hudson Soft', '1', 'Side-scrolling', 'Platformer / Breakout.', 'Rescue Honey and stop the invaders.', 'A unique blend of platforming and brick-breaking.', 'Based on an anime, it features side-scrolling stages that end in "Arkanoid" style boss battles, creating a very unusual gameplay loop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeda-shingen-japan', 'NES', 'Takeda Shingen (Japan)', '1988', 'Strategy, Simulation', 'Koei', '1', 'Top-down', 'Strategy / Sim.', 'Unify Japan as the legendary Takeda Shingen.', 'A historical grand strategy game.', 'Players manage provinces and lead samurai armies in tactical battles, focusing on the Sengoku period''s political and military drama.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeda-shingen-2-japan', 'NES', 'Takeda Shingen 2 (Japan)', '1990', 'Strategy, Simulation', 'Koei', '1', 'Top-down', 'Strategy / Sim.', 'Conquer Japan in this refined strategy sequel.', 'An expanded follow-up to the historical sim.', 'It features improved AI and more detailed map management, allowing for deeper diplomatic and military maneuvers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeshi-no-chousenjou-japan', 'NES', 'Takeshi no Chousenjou (Japan)', '1986', 'Adventure', 'Taito', '1', 'Side-scrolling', 'Action / Adventure.', 'Complete the absurd tasks to find the treasure.', 'One of the most "infamous" games in history.', 'Designed by Takeshi Kitano, it deliberately breaks game rules, requiring players to perform bizarre and frustrating tasks to progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('takeshi-no-sengoku-fuuunji-japan', 'NES', 'Takeshi no Sengoku Fuuunji (Japan)', '1988', 'Action, Strategy', 'Taito', '1', 'Side-scrolling', 'Board Game / Sim.', 'Become a legend in the Warring States period.', 'A historical board game with Takeshi Kitano''s touch.', 'It mixes traditional Japanese board game mechanics with historical events and a heavy dose of Kitano''s unique humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tale-spin-europe', 'NES', 'Tale Spin (Europe)', '1991', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling shooter.', 'Deliver cargo and stop Shere Khan''s pirates.', 'A Capcom flight-action game based on the Disney show.', 'You fly Baloo''s plane, which has a unique "reverse" mechanic, allowing you to fly backwards to navigate tight spaces and collect loot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tale-spin-usa', 'NES', 'Tale Spin (USA)', '1991', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling shooter.', 'Deliver cargo and stop Shere Khan''s pirates.', 'The North American version of the Disney classic.', 'Known for its colorful graphics and challenging boss fights, it captures the spirit of the cartoon with tight Capcom controls.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tales-of-phantasia-c', 'NES', 'Tales of Phantasia (C)', '1998', 'RPG', 'Homebrew', '1', 'Top-down', 'RPG.', 'Prevent the revival of the demon king Dhaos.', 'A Chinese-developed 8-bit port of the SNES classic.', 'An impressive (though unlicensed) attempt to squeeze the massive RPG into the Famicom, featuring simplified combat and visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('talespin-europe', 'NES', 'TaleSpin (Europe)', '1991', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Board Game.', 'Master Mahjong under the guidance of a pro.', 'A specialized Mahjong tutorial and simulation.', 'It features lessons from professional player Tamura, helping players learn the complex rules and strategies of the tile game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('talespin-usa', 'NES', 'TaleSpin (USA)', '1991', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Board Game.', 'Defeat high-level AI in Japanese Chess.', 'A professional-grade Shougi simulation.', 'It includes tutorials and historical matches, catering to serious players looking to improve their 8-bit Shougi skills.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tamura-koushou-mahjong-seminar-japan', 'NES', 'Tamura Koushou Mahjong Seminar (Japan)', '1990', 'Tabletop, Mahjong', 'Unknown', '1', 'Top-down', 'Board Game.', 'Master the art of Shougi in this final entry.', 'The peak of the Shougi Shinan series on Famicom.', 'Featuring the most advanced AI of the trilogy, it offers a steep challenge for even the most experienced Shougi enthusiasts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tanigawa-kouji-no-shougi-shinan-2-japan', 'NES', 'Tanigawa Kouji no Shougi Shinan 2 (Japan)', '1990', 'Tabletop, Shogi', 'Namco', '1', 'Top-down', 'Adventure.', 'Solve a complex case involving the passage of time.', 'A noir-style detective adventure (Jake Hunter).', 'Players use a menu-driven interface to interview suspects and search scenes in a mature, atmospheric mystery story.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tanigawa-kouji-no-shougi-shinan-3-japan', 'NES', 'Tanigawa Kouji no Shougi Shinan 3 (Japan)', '1991', 'Tabletop, Shogi', 'Namco', '1', 'Top-down', 'Adventure.', 'Solve a series of murders in Yokohama port.', 'The second entry in the Jake Hunter series.', 'Known for its jazz-inspired music and gritty urban setting, it''s a classic example of the Japanese adventure genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tantei-jinguuji-saburou---toki-no-sugiyuku-mama-ni-japan', 'NES', 'Tantei Jinguuji Saburou - Toki no Sugiyuku Mama ni (Japan)', '1988', 'Adventure', 'Data East', '1', 'Top-down', 'RPG.', 'Explore a world of Chinese mythology and occultism.', 'A unique and atmospheric occult RPG.', 'It blends traditional turn-based combat with a dark story involving exorcism and ancient spirits, featuring striking visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tantei-jinguuji-saburou---yokohamakou-renzoku-satsujin-jiken-japan', 'NES', 'Tantei Jinguuji Saburou - Yokohamakou Renzoku Satsujin Jiken (Japan)', '1988', 'Adventure', 'Data East', '1', 'Top-down', 'Beat ''em up.', 'Clean up the streets and rescue your brother.', 'A sequel to the classic "Renegade."', 'It features two-player co-op and a variety of urban stages, focusing on visceral brawling and weapon pick-ups.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tao-japan', 'NES', 'Tao (Japan)', '1989', 'Action, Adventure', 'Sunsoft', '1', 'Top-down', 'RPG.', 'Embark on a journey to save the world.', 'A rare unreleased prototype of a US RPG.', 'Featuring a style similar to Dragon Quest, it was cancelled before release, leaving behind a fully playable but lost 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('target-renegade-usa', 'NES', 'Target Renegade (USA)', '1989', 'Action, Beat ''em up', 'Imagineer', '2', 'Side-scrolling', 'Vertical shooter.', 'Destroy the enemy fleet in this unlicensed title.', 'A fast-paced shooter by the developer Sachen.', 'It features the typical high difficulty and colorful (if repetitive) sprites associated with the 90s unlicensed Asian market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taros-quest-usa-proto', 'NES', 'Taro''s Quest (USA) (Proto)', '1991', 'Action, Platformer', 'American Softworks', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Rescue the princesses in this wacky adventure.', 'A surreal game starring Japanese celeb Masashi Tashiro.', 'Players jump and solve puzzles in bizarre worlds, known for its odd humor and unconventional character design.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tasac-asia-unl', 'NES', 'Tasac (Asia) (Unl)', '1990', 'Action, Puzzle', 'Unknown', '1', 'Single-screen', 'Platformer / Puzzle.', 'Complete the quest with a "translated" title.', 'The English fan translation of the Tashiro Masashi game.', 'While the translation title is a bit cheeky, the patch is solid and allows players to navigate the game''s weird logic and levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tashiro-masashi-no-princess-ga-ippai-japan', 'NES', 'Tashiro Masashi no Princess ga Ippai (Japan)', '1989', 'Adult, Adventure', 'Namco', '1', 'Side-scrolling', 'Fighting / Adventure.', 'Compete in the martial arts tournament.', 'Based on the "Kinnikuman" (M.U.S.C.L.E.) spin-off.', 'It features a mix of top-down exploration and 2D fighting segments, following the story of the iconic ramen-loving martial artist.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tashiro-masashi-no-princess-ga-ippai-japan-en-by-suicidal-v10-~princesstual-orgy', 'NES', 'Tashiro Masashi no Princess ga Ippai (Japan) [En by Suicidal v1.0] (~Princesstual Orgy)', '1989', 'Adult, Adventure', 'Namco', '1', 'Side-scrolling', 'Side-scrolling action.', 'Fight through the post-apocalyptic city.', 'The original Japanese version of "Trojan."', 'Developed by Capcom, it features a sword-and-shield combat system in a gritty world filled with mutants and martial artists.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakae!!-rahmen-man---sakuretsu-choujin-102-gei-japan', 'NES', 'Tatakae!! Rahmen Man - Sakuretsu Choujin 102 Gei (Japan)', '1988', 'Action, Fighting', 'Toei Animation', '1', 'Side-scrolling', 'Side-scrolling action.', 'Fight the mutants with minor bug fixes.', 'A revised version of the Capcom classic.', 'This update polishes some of the collision detection during the shield-blocking sequences, improving the gameplay flow.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakai-no-banka-japan', 'NES', 'Tatakai no Banka (Japan)', '1989', 'Action, Adventure', 'Namco', '1', 'Side-scrolling', 'Sports / Baseball.', 'Outscore the competition in this pro sim.', 'A cinematic baseball game by Tecmo.', 'Known for its large sprites and "close-up" action shots during catches and slides, giving it a very TV-like presentation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tatakai-no-banka-japan-rev-a', 'NES', 'Tatakai no Banka (Japan) (Rev A)', '1989', 'Action, Adventure', 'Namco', '1', 'Side-scrolling', 'Sports / Football.', 'Lead your team to the victory in the pro league.', 'The debut of the legendary football franchise.', 'It simplified American football into an addictive arcade experience with a limited (but iconic) selection of plays.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-baseball-usa', 'NES', 'Tecmo Baseball (USA)', '1988', 'Sports, Baseball', 'Tecmo', '2', 'Top-down', 'Sports / Football.', 'Outplay the opposition in the ultimate NFL sim.', 'The game that changed sports titles forever.', 'Famous for Bo Jackson being "unstoppable," it was the first game to feature real NFL players (though not official team names).');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-bowl-japan', 'NES', 'Tecmo Bowl (Japan)', '1987', 'Sports, Football', 'Tecmo', '2', 'Top-down', 'Sports / Football.', 'Test the early version of the gridiron hit.', 'A rare development build of the NES classic.', 'Contains different UI colors and early player stats, showing how the gameplay was balanced before the final release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-bowl-usa', 'NES', 'Tecmo Bowl (USA)', '1987', 'Sports, Football', 'Tecmo', '2', 'Top-down', 'Sports / Football.', 'Win the championship with minor tweaks.', 'A revised North American release.', 'Addresses minor graphical glitches and stat errors, ensuring the most balanced version of the classic football experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-bowl-usa-beta', 'NES', 'Tecmo Bowl (USA) (Beta)', '1987', 'Sports, Football', 'Tecmo', '2', 'Top-down', 'Sports / RPG.', 'Lead Robert and his team to the World Cup.', 'A Westernized version of "Captain Tsubasa."', 'It replaces the anime characters with Western ones but keeps the incredible "cinematic" RPG-style soccer gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-bowl-usa-rev-a', 'NES', 'Tecmo Bowl (USA) (Rev A)', '1987', 'Sports, Football', 'Tecmo', '2', 'Top-down', 'Sports / RPG.', 'Win the Cup with localized Spanish text.', 'The Spanish-language edition of the soccer hit.', 'Hugely popular in Spain, it allowed fans to experience the strategic soccer drama in their own language.');
