INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles-ii---the-arcade-game-usa', 'NES', 'Teenage Mutant Ninja Turtles II - The Arcade Game (USA)', '1990', 'Action, Beat ''em up', 'Konami', '2', 'Side-scrolling', 'Beat ''em Up', 'Defeat enemies', 'Arcade brawler', 'Teenage Mutant Ninja Turtles II - The Arcade Game (USA) recreates cooperative arcade action at home.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles-ii---the-manhattan-project-japan', 'NES', 'Teenage Mutant Ninja Turtles II - The Manhattan Project (Japan)', '1991', 'Action, Beat ''em up', 'Konami', '2', 'Side-scrolling', 'Beat ''em up.', 'Stop Shredder and Krang in NYC.', 'Known in the US as "TMNT III: Manhattan Project."', 'Exclusive to the NES/Famicom, this sequel features unique special moves for each turtle and massive levels across New York.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teenage-mutant-ninja-turtles-iii---the-manhattan-project-usa', 'NES', 'Teenage Mutant Ninja Turtles III - The Manhattan Project (USA)', '1991', 'Action, Beat ''em up', 'Konami', '2', 'Side-scrolling', 'Beat ''em up.', 'Rescue Manhattan from being lifted into the sky.', 'The definitive 8-bit TMNT brawler.', 'Often cited as the best Turtles game on the system, featuring refined mechanics, surfboard levels, and iconic boss fights like Slash and Bebop.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tekken-2', 'NES', 'Tekken 2', '1997', 'Fighting', 'Unlicensed', '2', 'Side-view', 'Fighting.', 'Win the King of Iron Fist Tournament.', 'A surprising unlicensed 8-bit port of the 3D classic.', 'While obviously not 3D, it attempts to translate the Tekken roster and moveset into a 2D fighter with custom NES sprites.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-wo-kurau-japan', 'NES', 'Tenchi wo Kurau (Japan)', '1989', 'RPG', 'Capcom', '1', 'Top-down', 'Turn-based RPG.', 'Conquer ancient China during the Three Kingdoms.', 'Known in the West as "Destiny of an Emperor."', 'A deep Capcom RPG where you recruit generals and manage large armies instead of a small party, featuring strategic combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-wo-kurau-ii---shokatsu-koumei-den-japan', 'NES', 'Tenchi wo Kurau II - Shokatsu Koumei Den (Japan)', '1991', 'RPG', 'Capcom', '1', 'Top-down', 'Turn-based RPG.', 'Follow Zhuge Liang''s quest to unify the land.', 'The Japan-exclusive sequel to Destiny of an Emperor.', 'Widely considered one of the best RPGs on the Famicom, featuring a massive story, improved graphics, and a refined tactical system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenchi-wo-kurau-ii---shokatsu-koumei-den-japan-en-by-magic-destiny-v112-~destiny-of-an-emperor-ii---the-story-of-zhuge-liang', 'NES', 'Tenchi wo Kurau II - Shokatsu Koumei Den (Japan) [En by Magic Destiny v1.12] (~Destiny of an Emperor II - The Story of Zhuge Liang)', '1991', 'RPG', 'Capcom', '1', 'Top-down', 'Turn-based RPG.', 'Experience the epic sequel in English.', 'The fan translation of Tenchi wo Kurau II.', 'Allows Western fans to finally play the legendary sequel with a professional-quality translation of the complex historical plot.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tenkaichi-bushi---keru-naguuru-japan', 'NES', 'Tenkaichi Bushi - Keru Naguuru (Japan)', '1989', 'Action, Fighting', 'Namco', '2', 'Side-view', 'Fighting.', 'Defeat masters to become the ultimate martial artist.', 'A unique "chibi" style fighting game by Namco.', 'It features a deep move list for its time and allows players to customize their fighter''s skills as they progress through the tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tennis-europe', 'NES', 'Tennis (Europe)', '1984', 'Sports, Tennis', 'Nintendo', '2', 'Top-down', 'Sports / Tennis.', 'Outscore your opponent in a set of tennis.', 'Part of the Nintendo "Black Box" sports series.', 'Mario serves as the umpire in this classic title that defined the basic mechanics for almost every tennis game that followed.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tennis-japan-usa', 'NES', 'Tennis (Japan, USA)', '1984', 'Sports, Tennis', 'Nintendo', '2', 'Top-down', 'Sports / Tennis.', 'Win the championship match.', 'The global standard for 8-bit tennis.', 'Features multiple difficulty levels and a doubles mode, offering a simple but surprisingly deep simulation of the sport.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terao-no-dosukoi-oozumou-japan', 'NES', 'Terao no Dosukoi Oozumou (Japan)', '1989', 'Sports, Sumo', 'Tecmo', '1', 'Side-view', 'Sports / Sumo.', 'Rise through the ranks to become Yokozuna.', 'A realistic sumo wrestling simulation.', 'Players must manage training and timing in matches, featuring the real-life sumo star Terao and authentic tournament rules.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-europe', 'NES', 'Terminator 2 - Judgment Day (Europe)', '1991', 'Action', 'LJN', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'A cinematic action game based on the movie.', 'Features a variety of gameplay styles, including motorcycle chases, top-down shooting, and standard side-scrolling combat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-japan', 'NES', 'Terminator 2 - Judgment Day (Japan)', '1991', 'Action', 'LJN', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'The Famicom version of the T2 blockbuster.', 'It follows the movie''s plot closely, using digitized stills from the film to tell the story between the challenging levels.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-usa', 'NES', 'Terminator 2 - Judgment Day (USA)', '1991', 'Action', 'LJN', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect John Connor and stop Skynet.', 'The definitive North American movie tie-in.', 'Known for its high difficulty and the iconic T-800 sprite, it''s a solid representation of the 1991 sci-fi classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-usa-beta', 'NES', 'Terminator 2 - Judgment Day (USA) (Beta)', '1991', 'Action', 'LJN', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect John in this early development build.', 'A prototype featuring unfinished assets.', 'Shows early level designs and different enemy placements that were changed for the final commercial release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-usa-europe', 'NES', 'Terminator, The (USA, Europe)', '1991', 'Action', 'Mindscape', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect Sarah Connor from the T-800.', 'Based on the original 1984 film.', 'Players control Kyle Reese, fighting through a post-apocalyptic future and modern-day Los Angeles in a race against time.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terra-cresta-japan', 'NES', 'Terra Cresta (Japan)', '1985', 'Shooter', 'Nichibutsu', '2', 'Vertical scrolling', 'Vertical shooter.', 'Form a giant robot ship to defeat the Mandler.', 'A unique ship-merging arcade shooter.', 'You collect ship parts that attach to your craft; you can then "split" them to cover a wider area or stay merged for more power.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terra-cresta-usa', 'NES', 'Terra Cresta (USA)', '1985', 'Shooter', 'Nichibutsu', '2', 'Vertical scrolling', 'Vertical shooter.', 'Destroy the alien forces and their bases.', 'The North American release of the Nichibutsu hit.', 'A fast-paced shooter where power-ups change your firing pattern, requiring strategic use of the "formation" button.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetrastar---the-fighter-japan', 'NES', 'Tetrastar - The Fighter (Japan)', '1989', 'Action, Puzzle', 'Jaleco', '1', 'Single-screen', 'First-person shooter.', 'Defeat the enemy fleet in deep space.', 'A technically impressive pseudo-3D flight sim.', 'It pushes the NES hardware to create a 3D effect as you fly through space corridors and engage in dogfights with enemy ships.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetrastar---the-fighter-japan-en-by-gaijin-v10beta', 'NES', 'Tetrastar - The Fighter (Japan) [En by Gaijin v1.0Beta]', '1989', 'Action, Puzzle', 'Jaleco', '1', 'Single-screen', 'First-person shooter.', 'Save the galaxy with translated mission logs.', 'The fan translation of the Famicom-exclusive Tetrastar.', 'Makes the story and mission objectives clear, allowing players to fully enjoy the high-octane space combat and cinematic cutscenes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-europe', 'NES', 'Tetris (Europe)', '1988', 'Puzzle', 'Mirrorsoft', '2', 'Single-screen', 'Puzzle.', 'Clear lines by fitting falling blocks together.', 'The official Nintendo version for PAL regions.', 'The quintessential puzzle game that became a global phenomenon, featuring the iconic "A-Type" and "B-Type" music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-japan', 'NES', 'Tetris (Japan)', '1988', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Clear lines and achieve the highest score.', 'The original Famicom release by Bullet-Proof Software.', 'Features different controls (using Down to rotate) and a distinct selection of music compared to the Nintendo-developed version.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-japan-rev-a', 'NES', 'Tetris (Japan) (Rev A)', '1988', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Clear lines with updated mechanics.', 'A revised Japanese release of the BPS version.', 'Includes minor bug fixes and slightly adjusted block randomization to prevent unfair sequences of pieces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-japan-rev-b', 'NES', 'Tetris (Japan) (Rev B)', '1988', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Play the official Tetris with its famous theme.', 'A hack that restores the "Classic" Tetris music.', 'Replaces the standard tracks with the famous "Korobeiniki" folk song that players expected from other versions of the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-title-music-restoration', 'NES', 'Tetris (Title Music Restoration)', '1988', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Clear lines and see the rocket launch.', 'The most famous version of Tetris in history.', 'Developed by Nintendo, it’s the competitive standard for the "Classic Tetris World Championship" today.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-usa', 'NES', 'Tetris (USA)', '1989', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Play the legendary 2-player mode.', 'The famous unlicensed version by Tengen.', 'Widely considered superior to the Nintendo version for its 2-player co-op and versus modes, which were missing from the official one.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-usa-unl', 'NES', 'Tetris (USA) (Unl)', '1989', 'Puzzle', 'Atari Games', '2', 'Single-screen', 'Puzzle.', 'Match colored blocks to clear the screen.', 'A sequel focusing on color-matching mechanics.', 'Unlike the original, you must align three blocks of the same color to clear them, similar to Dr. Mario but with Tetris pieces.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-europe', 'NES', 'Tetris 2 (Europe)', '1993', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Match colored blocks to clear the screen.', 'The North American sequel to the puzzle hit.', 'Features a variety of modes, including a puzzle mode where you must clear specific patterns in a limited number of moves.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-usa', 'NES', 'Tetris 2 (USA)', '1993', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Use bombs to clear massive clusters of blocks.', 'A Japan-exclusive 2-in-1 puzzle package.', 'Includes "Bombliss," a strategic variant where certain blocks are bombs that explode when a line is cleared, creating chain reactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-+-bombliss-japan', 'NES', 'Tetris 2 + Bombliss (Japan)', '1991', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Master the bombs with minor bug fixes.', 'A revised version of the Bombliss collection.', 'Polishes the menus and addresses minor graphical glitches in the high-speed levels of the Bombliss mode.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tetris-2-+-bombliss-japan-rev-a', 'NES', 'Tetris 2 + Bombliss (Japan) (Rev A)', '1991', 'Puzzle', 'Nintendo', '2', 'Single-screen', 'Puzzle.', 'Master the bombs with minor bug fixes.', 'A revised version of the Bombliss collection.', 'Polishes the menus and addresses minor graphical glitches in the high-speed levels of the Bombliss mode.');
