INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tokkyuu-shirei---solbrain-japan', 'NES', 'Tokkyuu Shirei - Solbrain (Japan)', '1991', 'Action, Platformer', 'Toei Company', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the metal army with translated story.', 'The fan translation of the Japanese Solbrain.', 'For fans who prefer the original Tokusatsu license over the Westernized Shatterhand presentation.');
