INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tokoro-san-no-mamoru-mo-semeru-mo-japan', 'NES', 'Tokoro San no Mamoru mo Semeru mo (Japan)', '1987', 'Action, Party', 'Namco', '1', 'Side-scrolling', 'Platformer.', 'Rescue Tuffy from the attic.', 'A charming platformer based on the classic cartoon.', 'You control Jerry, using marbles and hammers to fight through household areas, from the basement to the roof.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-and-tuffy-europe', 'NES', 'Tom & Jerry (and Tuffy) (Europe)', '1991', 'Action, Platformer', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Platformer.', 'Defeat Tom and save your little nephew.', 'The Japanese release of the Hi-Tech Expressions game.', 'Known for its solid graphics and "mouse-sized" perspective of the world, making everyday objects look giant.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-and-tuffy-japan', 'NES', 'Tom & Jerry (and Tuffy) (Japan)', '1991', 'Action, Platformer', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Platformer.', 'Outsmart Tom in this 8-bit chase.', 'The North American version of the cartoon hit.', 'A surprisingly good licensed game with tight jumping and fun boss battles against the famous cat.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-and-tuffy-usa', 'NES', 'Tom & Jerry (and Tuffy) (USA)', '1991', 'Action, Platformer', 'Hi Tech Expressions', '1', 'Side-scrolling', 'Platformer.', 'Navigate new levels in this unlicensed title.', 'A pirate sequel often found on Asian multicarts.', 'Usually a hack of a different platformer with Jerry''s sprite inserted, serving as an "unofficial" third entry.');
