INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toukyou-pachi-slot-adventure-japan-rev-a', 'NES', 'Toukyou Pachi Slot Adventure (Japan) (Rev A)', '1991', 'Gambling, Simulation', 'Coconuts Japan', '1', 'Top-down', 'Simulation / Casino.', 'Win big at the Pachi-Slot machines.', 'A realistic gambling simulation with a story mode.', 'Players explore a virtual city, managing their money and trying to hit the jackpot on various themed slot machines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tower-of-druaga-the-japan', 'NES', 'Tower of Druaga, The (Japan)', '1984', 'Action, Adventure', 'Namco', '1', 'Top-down', 'Action / RPG.', 'Climb the 60 floors to rescue Princess Ki.', 'A legendary Namco arcade port.', 'Known for its cryptic secrets, each floor requires a specific action (like killing enemies in order) to reveal a hidden treasure chest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toxic-crusaders-usa', 'NES', 'Toxic Crusaders (USA)', '1991', 'Action, Platformer', 'Rare', '2', 'Side-scrolling', 'Beat ''em up.', 'Clean up Tromaville and stop the radiation.', 'Based on the Troma cartoon series.', 'You control Toxie in a side-scrolling brawler, fighting through mutant thugs and radioactive hazards with a mop as your weapon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toy-story-unl', 'NES', 'Toy Story (Unl)', '1995', 'Action, Platformer', 'Unlicensed', '1', 'Side-scrolling', 'Platformer.', 'Reach the end of the house as Woody.', 'An unlicensed 8-bit port of the 16-bit hit.', 'Despite being a bootleg, it tries to replicate the levels and "pre-rendered" look of the SNES/Genesis versions of the Disney movie.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('track-&-field-usa', 'NES', 'Track & Field (USA)', '1987', 'Sports, Athletics', 'Konami', '2', 'Side-view', 'Sports / Olympics.', 'Qualify in several Olympic events.', 'The home version of the Konami arcade classic.', 'Players compete in events like the 100m dash and long jump, requiring rapid button-mashing to gain speed and power.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('track-&-field-ii-europe', 'NES', 'Track & Field II (Europe)', '1988', 'Sports, Athletics', 'Konami', '2', 'Side-view', 'Sports / Olympics.', 'Win gold medals in a variety of events.', 'A massive improvement over the original.', 'Features better graphics and more complex events like fencing, archery, and triple jump, offering a much deeper sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('track-&-field-ii-usa', 'NES', 'Track & Field II (USA)', '1988', 'Sports, Athletics', 'Konami', '2', 'Side-view', 'Sports / Olympics.', 'Represent your country and win the gold.', 'The definitive North American Olympic sim.', 'Known for its high production values and intense 2-player competition across several challenging disciplines.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('track-&-field-ii-usa-rev-a', 'NES', 'Track & Field II (USA) (Rev A)', '1988', 'Sports, Athletics', 'Konami', '2', 'Side-view', 'Sports / Olympics.', 'Win the gold with minor stat fixes.', 'A revised version of the Konami sports hit.', 'This update polishes some scoring bugs in the gymnastics and swimming events for a more fair competition.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('track-&-field-in-barcelona-europe', 'NES', 'Track & Field in Barcelona (Europe)', '1992', 'Sports, Athletics', 'Konami', '2', 'Side-view', 'Sports / Olympics.', 'Compete in the 1992 Summer Olympics.', 'A European-exclusive Olympic update.', 'Released to coincide with the Barcelona games, it features updated sprites and a new selection of events for PAL gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transformers---comvoy-no-nazo-japan', 'NES', 'Transformers - Comvoy no Nazo (Japan)', '1986', 'Action, Adventure', 'Konami', '1', 'Side-scrolling', 'Side-scrolling action.', 'Solve the mystery of Optimus Prime''s death.', 'A notoriously difficult Transformers game.', 'You control Ultra Magnus. The game is infamous for its tiny bullets, instant deaths, and nearly impossible level designs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transformers---comvoy-no-nazo-japan-en-by-stardust-crusaders-v10-~transformers-the---mystery-of-comvoy', 'NES', 'Transformers - Comvoy no Nazo (Japan) [En by Stardust Crusaders v1.0] (~Transformers, The - Mystery of Comvoy)', '1986', 'Action, Adventure', 'Konami', '1', 'Side-scrolling', 'Side-scrolling action.', 'Solve the mystery with translated text.', 'The English fan translation of the Transformers hit.', 'Clarifies the story and menus, though it doesn''t make the punishing 8-bit difficulty any easier!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('treasure-master-usa', 'NES', 'Treasure Master (USA)', '1991', 'Action, Platformer', 'American Softworks', '1', 'Side-scrolling', 'Action / Platformer.', 'Find the secret codes to win real-life prizes.', 'A game tied to a 1991 MTV contest.', 'Players had to finish the game and use codes to enter a sweepstakes. It features varied worlds and creative tool-based puzzles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('triathron-the-japan', 'NES', 'Triathron, The (Japan)', '1987', 'Sports, Triathlon', 'Jaleco', '1', 'Top-down', 'Sports / Racing.', 'Complete the swim, bike, and run legs.', 'A rare 8-bit simulation of a Triathlon.', 'It requires careful stamina management across three distinct gameplay styles to finish the grueling race in first place.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trog!-europe', 'NES', 'Trog! (Europe)', '1990', 'Action, Arcade', 'Visual Concepts', '2', 'Isometric', 'Puzzle / Strategy.', 'Collect all eggs before the cavemen catch you.', 'A quirky arcade port with claymation-style art.', 'You play as a dinosaur in a maze, using power-ups like "pineapple" to turn into a T-Rex and eat your pursuers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trog!-usa', 'NES', 'Trog! (USA)', '1990', 'Action, Arcade', 'Visual Concepts', '2', 'Isometric', 'Puzzle / Strategy.', 'Outsmart the cavemen in this prehistoric maze.', 'The North American version of the Acclaim hit.', 'Known for its colorful graphics and addictive 2-player cooperative mode, it''s a unique take on the "Pac-Man" formula.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trojan-europe', 'NES', 'Trojan (Europe)', '1986', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the warlord Achilles in a wasteland.', 'A post-apocalyptic sword-fighting game.', 'As a bionic warrior with a shield, you must time your blocks and strikes perfectly to survive mutants and traps.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trojan-usa', 'NES', 'Trojan (USA)', '1986', 'Action, Platformer', 'Capcom', '1', 'Side-scrolling', 'Side-scrolling action.', 'Defeat the warlord Achilles in a wasteland.', 'The North American Capcom arcade port.', 'Features hidden rooms and a "Vs. Mode" where two players can duel each other using the game''s combat mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trolls-in-crazyland-the-europe', 'NES', 'Trolls in Crazyland, The (Europe)', '1991', 'Action, Platformer', 'Flair Software', '1', 'Side-scrolling', 'Platformer.', 'Rescue your friends from the evil nightmare.', 'A European exclusive starring the famous toys.', 'It’s actually a reskin of the Japanese game "Doki! Doki! Yuuenchi," featuring a kid with a powerful soccer ball attack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trolls-on-treasure-island-usa-unl', 'NES', 'Trolls on Treasure Island (USA) (Unl)', '1993', 'Action, Platformer', 'Unlicensed', '1', 'Side-scrolling', 'Platformer.', 'Collect treasures across a magical island.', 'An unlicensed game by American Video Ent.', 'A simple but charming platformer where you navigate a Troll through various stages filled with hazards and secrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuppari-oozumou-japan', 'NES', 'Tsuppari Oozumou (Japan)', '1987', 'Sports, Sumo', 'Technos Japan', '2', 'Side-view', 'Sports / Sumo.', 'Rise to the rank of Yokozuna.', 'The first Sumo game by Tecmo.', 'It introduced "chibi" wrestlers and a RPG-like growth system, where your wrestler gets stronger after every tournament.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuppari-wars-japan', 'NES', 'Tsuppari Wars (Japan)', '1991', 'Action, Fighting', 'Capcom', '2', 'Side-view', 'Sports / Strategy.', 'Conquer the sumo world through battles.', 'A sequel that adds a territory-conquest map.', 'It mixes traditional sumo matches with a strategic map where you must defeat rival stables to dominate Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuri-kichi-sanpei---blue-marlin-hen---english-v094', 'NES', 'Tsuri Kichi Sanpei - Blue Marlin Hen - English v094', '1989', 'Sports, Fishing', 'Naxat Soft', '1', 'Side-view', 'Fishing / RPG.', 'Catch the legendary Blue Marlin.', 'The fan translation of the popular fishing series.', 'It makes the complex fishing equipment and weather data understandable for non-Japanese speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuri-kichi-sanpei---blue-marlin-hen-japan', 'NES', 'Tsuri Kichi Sanpei - Blue Marlin Hen (Japan)', '1989', 'Sports, Fishing', 'Naxat Soft', '1', 'Side-view', 'Fishing / RPG.', 'Become the world''s best fisherman.', 'Based on a famous manga about a boy who loves fishing.', 'More than just a sports game, it features a story mode and deep mechanics for bait, tackle, and reeling in big fish.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tsuru-pika-hagemaru---mezase!-tsuru-seko-no-akashi-japan', 'NES', 'Tsuru Pika Hagemaru - Mezase! Tsuru Seko no Akashi (Japan)', '1988', 'Action, Platformer', 'Epoch', '1', 'Side-scrolling', 'Platformer / Action.', 'Prove your "cheapness" to win the trophy.', 'A hilarious game based on a comedy manga.', 'Players must act "cheaply" (avoiding spending) while navigating surreal levels filled with slapstick humor.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turbo-racing-europe', 'NES', 'Turbo Racing (Europe)', '1989', 'Racing', 'Loriciels', '2', 'Top-down', 'Racing.', 'Win the Formula 1 World Championship.', 'A high-speed racer known as "Al Alour Jr. Racing."', 'It features a cockpit view and customizable cars, allowing players to adjust wings and tires for different tracks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turma-da-monica-dooly-bravo-land-hack', 'NES', 'Turma da Monica (Dooly Bravo Land Hack)', '1991', 'Action, Platformer', 'Bootleg', '1', 'Side-scrolling', 'Platformer.', 'Save your friends in this Brazilian hack.', 'A hack of the Korean game "Dooly Bravo Land."', 'It replaces the characters with Mônica and her gang, created for the massive Brazilian NES/Master System market.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-cobra-usa', 'NES', 'Twin Cobra (USA)', '1989', 'Shooter', 'Toaplan', '2', 'Vertical scrolling', 'Vertical shooter.', 'Destroy the enemy tanks and aircraft.', 'A port of the legendary Toaplan arcade shmup.', 'Known for its orange helicopter and the devastating "circle bomb" that clears the screen of enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('twin-eagle---revenge-joes-brother-japan', 'NES', 'Twin Eagle - Revenge Joe''s Brother (Japan)', '1988', 'Shooter', 'Setsu', '2', 'Vertical scrolling', 'Vertical shooter.', 'Avenge Joe''s brother by destroying the cartel.', 'A military-themed helicopter shooter.', 'It features a unique art style using digitized textures and a heavy focus on destroying ground buildings for extra points.');
