INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vegas-connection---casino-kara-ai-wo-komete-japan', 'NES', 'Vegas Connection - Casino Kara Ai wo Komete (Japan)', '1990', 'Gambling, Simulation', 'ASCII', '1', 'Top-down', 'Board Game / Casino.', 'Solve a mystery while winning in the casino.', 'A unique blend of adventure and gambling.', 'You travel to Las Vegas to solve a missing person case, playing various casino games to earn money and find clues.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vegas-dream-usa', 'NES', 'Vegas Dream (USA)', '1990', 'Gambling, Simulation', 'HAL Laboratory', '1', 'Top-down', 'Simulation / Casino.', 'Turn your $700 into a fortune in Las Vegas.', 'A social casino simulator with random events.', 'Beyond the gambling (slots, blackjack, etc.), the game features "encounters" that can lead to making friends, getting robbed, or getting married.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('venice-beach-volleyball-usa-unl', 'NES', 'Venice Beach Volleyball (USA) (Unl)', '1992', 'Sports, Volleyball', 'Unlicensed', '2', 'Side-view', 'Sports.', 'Win the 2-on-2 beach volleyball tournament.', 'An unlicensed sports game by American Video Ent.', 'A decent volleyball title with colorful graphics, focusing on positioning and timing your spikes under the California sun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('venus-senki---back-the-city-japan', 'NES', 'Venus Senki - Back the City (Japan)', '1989', 'Action, Platformer', 'Telenet Japan', '1', 'Side-scrolling', 'Strategy / RPG.', 'Fight the Ishtar army on the surface of Mars.', 'A tactical strategy game based on the anime.', 'You command "monobikes" and tanks in grid-based movement, switching to an action screen for combat encounters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('venus-senki---back-the-city-japan-en-by-j2e-v20-~venus-wars-the', 'NES', 'Venus Senki - Back the City (Japan) [En by J2e v2.0] (~Venus Wars, The)', '1989', 'Action, Platformer', 'Telenet Japan', '1', 'Side-scrolling', 'Strategy / RPG.', 'Conquer Mars with fully translated text.', 'The English fan translation of Venus Senki.', 'Essential for managing the tactical units and following the cinematic story based on Yoshikazu Yasuhiko''s classic manga.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vice---project-doom-usa', 'NES', 'Vice - Project Doom (USA)', '1991', 'Action, Platformer', 'Aicom', '1', 'Side-scrolling', 'Multi-genre Action.', 'Uncover the conspiracy of the "BEDA" corporation.', 'A high-octane cinematic action masterpiece.', 'It seamlessly blends driving stages, gallery shooting, and side-scrolling platforming with incredible cutscenes and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('videomation-usa', 'NES', 'Videomation (USA)', '1991', 'Edutainment, Creativity', 'Lucasfilm Games', '1', 'Top-down', 'Creative / Tool.', 'Create your own 8-bit digital art and animations.', 'A primitive but fun drawing tool for NES.', 'Features various brushes, stamps, and color palettes, allowing players to save their creations to a VCR or a battery backup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vindicators-usa-unl', 'NES', 'Vindicators (USA) (Unl)', '1990', 'Action, Shooter', 'Atari Games', '2', 'Isometric', 'Tank Shooter.', 'Destroy the enemy base and collect fuel.', 'An unlicensed port of the Atari arcade game.', 'A top-down shooter where you control a tank, navigating corridors and managing fuel levels while fighting off defensive turrets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('viva!-las-vegas-japan', 'NES', 'Viva! Las Vegas (Japan)', '1989', 'Gambling, Simulation', 'Jaleco', '1', 'Top-down', 'Simulation / Casino.', 'Become a high roller in the city of sin.', 'The Japanese version of "Vegas Dream."', 'Featuring the same blend of casino games and life events, but with localized text and slightly different social interactions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('volguard-ii-japan', 'NES', 'Volguard II (Japan)', '1985', 'Shooter', 'DB Soft', '1', 'Vertical scrolling', 'Side-scrolling shooter.', 'Pilot the transforming robot and save Earth.', 'A technical shooter by DB-Soft.', 'Your ship can transform into a giant robot if you collect the right parts, requiring you to manage energy levels for different forms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('volleyball-usa-europe', 'NES', 'Volleyball (USA, Europe)', '1985', 'Sports, Volleyball', 'Nintendo', '2', 'Side-view', 'Sports.', 'Lead your national team to the world title.', 'Part of Nintendo''s original "Black Box" sports.', 'A simple but effective simulation of volleyball, featuring men''s and women''s teams and a focus on serving and spiking timing.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wacky-races-usa', 'NES', 'Wacky Races (USA)', '1992', 'Action, Racing', 'Hi Tech Expressions', '2', 'Side-scrolling', 'Platformer.', 'Stop Dick Dastardly and Muttley from winning.', 'A high-quality platformer based on the cartoon.', 'You control Muttley through various stages, collecting "diamonds" to unlock special abilities like flying or throwing bombs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-japan', 'NES', 'Wagan Land (Japan)', '1988', 'Action, Puzzle', 'Namco', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Defeat the Dr. Devil with the power of words.', 'A cute and unique platformer by Namco.', 'You play as a mechanical dinosaur. Instead of killing bosses, you play word games and memory matches to win.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-japan-en-by-alanmidas-v20001222-~wagyan-land', 'NES', 'Wagan Land (Japan) [En by AlanMidas v20001222] (~Wagyan Land)', '1988', 'Action, Puzzle', 'Namco', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Save the island with translated word puzzles.', 'The English fan translation of the first Wagan Land.', 'This patch is vital because the boss battles rely on Japanese word association, now adapted for English speakers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-2-japan', 'NES', 'Wagan Land 2 (Japan)', '1990', 'Action, Puzzle', 'Namco', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Embark on a bigger quest to save the Wagan tribe.', 'An expanded sequel with more mini-games.', 'Introduces new power-ups and even more creative boss encounters, refining the unique "non-violent" combat system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-2-japan-en-by-abstract-crouton-v10-graphic-hack-by-terminus-v10-~wagyan-land-2', 'NES', 'Wagan Land 2 (Japan) [En by Abstract Crouton v1.0] [Graphic Hack by Terminus v1.0] (~Wagyan Land 2)', '1990', 'Action, Puzzle', 'Namco', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Defeat the bosses with translated puzzles.', 'The English fan translation of the second entry.', 'Features translated tiles for the mini-games, making the "Shiritori" battles playable for Western gamers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wagan-land-3-japan', 'NES', 'Wagan Land 3 (Japan)', '1992', 'Action, Puzzle', 'Namco', '1', 'Side-scrolling', 'Platformer / Puzzle.', 'Travel to the space colony to save your people.', 'The final Famicom entry in the Wagan trilogy.', 'Adds gravity-defying stages and new mini-games, maintaining the series'' charm and unique puzzle-based boss fights.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wai-wai-world-japan', 'NES', 'Wai Wai World (Japan)', '1988', 'Action, Platformer', 'Konami', '2', 'Side-scrolling', 'Action / Platformer.', 'Rescue Konami''s biggest stars from the villain.', 'The ultimate Konami crossover game.', 'You can switch between Simon Belmont, Mikey (Goonies), Goemon, and more, each with their own classic abilities and music.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wai-wai-world-japan-en-by-dylan-robley-v10', 'NES', 'Wai Wai World (Japan) [En by Dylan Robley v1.0]', '1988', 'Action, Platformer', 'Konami', '2', 'Side-scrolling', 'Action / Platformer.', 'Save the Konami stars with translated text.', 'The English fan translation of the crossover hit.', 'Clarifies the character-specific quests and the "Gradius" style final stage, making it a must-play for Konami fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wai-wai-world-2---sos!!-paseri-jou-japan', 'NES', 'Wai Wai World 2 - SOS!! Paseri Jou (Japan)', '1991', 'Action, Platformer', 'Konami', '2', 'Side-scrolling', 'Platformer / Shooter.', 'Stop the evil Parsley Castle from being taken.', 'A more linear and colorful crossover sequel.', 'It plays like a "greatest hits" of Konami games, with levels parodying Contra, Castlevania, and Frogger with a cute aesthetic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wai-wai-world-2---sos!!-paseri-jou-japan-en-by-vice-v101-~wai-wai-world-2---sos-from-parsley-castle', 'NES', 'Wai Wai World 2 - SOS!! Paseri Jou (Japan) [En by Vice v1.01] (~Wai Wai World 2 - SOS from Parsley Castle)', '1991', 'Action, Platformer', 'Konami', '2', 'Side-scrolling', 'Platformer / Shooter.', 'Save the castle with translated dialogue.', 'The English fan translation of the second crossover.', 'A perfect translation that highlights the humor and the many cameos from the Konami universe.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wait-and-see-russia-unl', 'NES', 'Wait and See (Russia) (Unl)', '1993', 'Puzzle', 'Unlicensed', '1', 'Single-screen', 'Puzzle.', 'Clear the board in this rare unlicensed title.', 'A Russian-made unlicensed puzzle game.', 'Known for its odd title and simple logic mechanics, it''s a curious piece of the Eastern European 8-bit development scene.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wall-street-kid-usa', 'NES', 'Wall Street Kid (USA)', '1990', 'Simulation, Finance', 'SOFEL', '1', 'Top-down', 'Simulation / Strategy.', 'Make a fortune in the stock market to get rich.', 'A unique financial simulation game.', 'You must research stocks, buy low/sell high, and maintain a social life to inherit a massive family fortune.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wally-bear-and-the-no-gang-usa-unl', 'NES', 'Wally Bear and the No Gang (USA) (Unl)', '1992', 'Edutainment', 'American Softworks', '1', 'Side-scrolling', 'Platformer.', 'Say no to drugs in this educational adventure.', 'An unlicensed "Anti-Drug" game by Wisdom Tree.', 'You control a skateboarding bear through urban levels, avoiding hazards and answering questions about making healthy choices.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wang-zi-fu-chou-ji-china-unl', 'NES', 'Wang Zi Fu Chou Ji (China) (Unl)', '1993', 'Action, Platformer', 'Unlicensed', '1', 'Side-scrolling', 'Turn-based RPG.', 'Embark on a Chinese fantasy quest.', 'An unlicensed Chinese RPG.', 'Features a traditional RPG structure with turn-based battles, often featuring impressive (if pirated) musical tracks and art assets.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanpaku-duck-yume-bouken-japan', 'NES', 'Wanpaku Duck Yume Bouken (Japan)', '1989', 'Action, Platformer', 'Konami', '1', 'Side-scrolling', 'Platformer.', 'Travel the world for treasure with Scrooge.', 'The Japanese version of "DuckTales."', 'Developed by Capcom, it’s a masterpiece of level design and music, following the adventures of Scrooge McDuck.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanpaku-kokkun-no-gourmet-world-japan', 'NES', 'Wanpaku Kokkun no Gourmet World (Japan)', '1990', 'Action, Platformer', 'Taito', '1', 'Side-scrolling', 'Platformer.', 'Fight food-themed enemies as a tiny chef.', 'Known in the West as "Panic Restaurant."', 'A very charming and high-quality late-NES title where you use kitchen utensils like frying pans to fight evil ingredients.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanpaku-kokkun-no-gourmet-world-japan-en-by-spoony-bard-v10-~naughty-kokkuns-gourmet-world', 'NES', 'Wanpaku Kokkun no Gourmet World (Japan) [En by Spoony Bard v1.0] (~Naughty Kokkun''s Gourmet World)', '1990', 'Action, Platformer', 'Taito', '1', 'Side-scrolling', 'Action / Platformer', 'Collect food', 'Action platformer', 'Wanpaku Kokkun no Gourmet World is a lighthearted action game where players gather food while avoiding enemies in colorful stages.');
