INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune-gamer-edition', 'NES', 'Wheel of Fortune Gamer Edition', '1989', 'Puzzle', 'Quiz Unlicensed', '2', 'Top-down', 'Quiz / Board Game.', 'Solve the word puzzles to win.', 'A specialized edition of Wheel of Fortune.', 'Featuring more challenging categories and a faster pace, aimed at fans of the TV show who want a harder difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheel-of-fortune-starring-vanna-white-usa', 'NES', 'Wheel of Fortune Starring Vanna White (USA)', '1992', 'Game Show', 'Gameloft', '1', 'Static screens', 'Quiz / Board Game.', 'Spin the wheel and solve the phrase.', 'The most polished version of the TV show game.', 'It features digitized images of Vanna White and a vast library of puzzles, capturing the true feel of the late 80s game show.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-time-is-carmen-sandiego-usa', 'NES', 'Where in Time is Carmen Sandiego (USA)', '1989', 'Educational, Adventure', 'Broderbund', '1', 'Top-down', 'Educational.', 'Track the thief through different historical eras.', 'A time-traveling detective mystery.', 'Players must solve clues about history and geography to jump through time, trying to catch Carmen and her gang of crooks.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wheres-waldo-usa', 'NES', 'Where''s Waldo (USA)', '1988', 'Puzzle, Adventure', 'THQ', '1', 'Top-down', 'Hidden Object.', 'Find Waldo in the crowded images.', 'An 8-bit version of the famous "Search and Find" books.', 'It challenges players to find the iconic character in pixelated scenes before the timer runs out, though the low resolution makes it quite hard!');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('white-lion-densetsu-japan', 'NES', 'White Lion Densetsu (Japan)', '1989', 'Action, RPG', 'Kemco', '1', 'Side-scrolling', 'Turn-based RPG.', 'Find the 7 legendary spears with a white lion.', 'A unique RPG known as "Legend of the White Lion."', 'You play as a girl named Maria, accompanied by a ghostly white lion, in a quest filled with spirits and magical artifacts.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('who-framed-roger-rabbit-usa', 'NES', 'Who Framed Roger Rabbit (USA)', '1989', 'Action, Adventure', 'Rare', '1', 'Side-scrolling', 'Action / Adventure.', 'Find the will and clear Roger''s name.', 'A top-down detective game by LJN.', 'Based on the movie, you explore Hollywood, talk to characters, and avoid the Weasels in a mix of exploration and mini-games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('whompem-usa', 'NES', 'Whomp''Em (USA)', '1991', 'Action, Platform', 'Jaleco', '1', 'Side-scrolling', 'Side-scrolling action.', 'Collect the magic totems from different lands.', 'The Western version of "Saiyuuki World 2."', 'You play as a Native American warrior with a spear. It’s a fantastic platformer where you gain new abilities after defeating each boss.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('widget-usa', 'NES', 'Widget (USA)', '1992', 'Action, Platform', 'Atlus', '1', 'Side-scrolling', 'Side-scrolling action.', 'Protect the environment and stop Ratchet.', 'Based on the "Widget the World Watcher" cartoon.', 'Widget can transform into different forms (like a bird or a cannon) to navigate levels and fight polluters.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-gunman-japan-usa', 'NES', 'Wild Gunman (Japan, USA)', '1984', 'Shooter', 'Nintendo', '1', 'First-person', 'Light Gun / Shooter.', 'Draw and shoot the outlaws before they fire.', 'The classic Zapper-based Western duel.', 'Famous for its "Wait... FIRE!" mechanic, testing your reaction speed against various 8-bit desperados.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wild-gunman-world-rev-a', 'NES', 'Wild Gunman (World) (Rev A)', '1984', 'Shooter', 'Nintendo', '1', 'First-person', 'Light Gun / Shooter.', 'Outdraw the gunmen with minor bug fixes.', 'A revised version of the Nintendo shooter.', 'Includes small graphical tweaks and better hit detection for the Zapper peripheral.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('willow-europe', 'NES', 'Willow (Europe)', '1989', 'Action, RPG', 'Capcom', '1', 'Top-down', 'Action / Adventure.', 'Defeat Queen Bavmorda and save the baby Elora.', 'A high-quality top-down adventure by Capcom.', 'Unlike the movie, it''s a deep RPG/Adventure hybrid where you level up and gain new magic swords and spells.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('willow-japan', 'NES', 'Willow (Japan)', '1989', 'Action, RPG', 'Capcom', '1', 'Top-down', 'Action / Adventure.', 'Save the world of Nelwyn in 8-bit.', 'The Famicom release of the Lucasfilm epic.', 'Known for its beautiful soundtrack and challenging puzzles, it''s widely considered a hidden gem of the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('willow-usa', 'NES', 'Willow (USA)', '1989', 'Action, RPG', 'Capcom', '1', 'Top-down', 'Action / Adventure.', 'Embark on the quest to save the baby Elora.', 'The definitive North American version of the hit.', 'A sprawling adventure with a massive map and a password system to track your progress through the dangerous fantasy world.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wily-&-light-no-rockboard---thats-paradise-japan', 'NES', 'Wily & Light no Rockboard - That''s Paradise (Japan)', '1991', 'Board Game', 'Capcom', '1-4', 'Top-down', 'Board Game / Strategy.', 'Buy properties and build labs to win.', 'A Mega Man themed board game.', 'Players choose characters like Dr. Light or Roll, moving across a board and using "item cards" to sabotage opponents.');
