INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wily-&-light-no-rockboard---thats-paradise-japan-en-by-interordi-v11-rockman-version', 'NES', 'Wily & Light no Rockboard - That''s Paradise (Japan) [En by Interordi v1.1] (Rockman Version)', '1991', 'Board Game', 'Capcom', '1-4', 'Top-down', 'Board Game / Strategy.', 'Master the board with Rockman terminology.', 'The English translation using original Japanese names.', 'Keeps the "Rockman" and "Forte" naming conventions for purists of the original Japanese series.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('win-lose-or-draw-usa', 'NES', 'Win, Lose or Draw (USA)', '1990', 'Party, Quiz', 'LJN', '1-2', 'Top-down', 'Quiz / Board Game.', 'Guess the drawing before the timer expires.', 'Based on the TV show where players draw clues.', 'A digital take on Pictionary, featuring a variety of objects and phrases for players to identify from 8-bit sketches.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wing-of-madoola-the-japan', 'NES', 'Wing of Madoola, The (Japan)', '1986', 'Action, Platform', 'Sunsoft', '1', 'Side-scrolling', 'Side-scrolling action.', 'Retrieve the Wing of Madoola from the demon king.', 'A fast-paced fantasy action game by Sunsoft.', 'You play as the warrior Lucia, who gains power-ups and magic as she explores large, multi-connected stages.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-games-usa', 'NES', 'Winter Games (USA)', '1987', 'Sports', 'Epyx', '1-8', 'Various', 'Sports / Olympics.', 'Compete for the gold in winter disciplines.', 'An Epyx sports classic ported to NES.', 'Includes events like ski jumping, bobsled, and figure skating, requiring precision and rhythm to score high points.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-games-usa-rev-a', 'NES', 'Winter Games (USA) (Rev A)', '1987', 'Sports', 'Epyx', '1-8', 'Various', 'Sports / Olympics.', 'Win the winter gold with minor tweaks.', 'A revised release of the winter sports title.', 'Polishes the physics in the skiing events for a more consistent gameplay experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wisdom-boy-china-unl', 'NES', 'Wisdom Boy (China) (Unl)', '1990', 'Action, Platform', 'Unlicensed', '1', 'Side-scrolling', 'Puzzle / RPG.', 'Solve logic puzzles to progress.', 'An unlicensed Chinese educational game.', 'Features a variety of mini-games designed to test memory and math skills within a fantasy setting.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wits-japan', 'NES', 'Wit''s (Japan)', '1990', 'Puzzle', 'Athena', '1', 'Top-down', 'Maze / Action.', 'Trap your opponents in this "Snake" style game.', 'A top-down competitive maze game.', 'Similar to the "Light Cycles" from Tron, players must force rivals to crash into their trails to be the last one standing.');
