INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry---proving-grounds-of-the-mad-overlord-japan', 'NES', 'Wizardry - Proving Grounds of the Mad Overlord (Japan)', '1987', 'RPG', 'ASCII', '1', 'First-person', 'First-person RPG.', 'Find the amulet stolen by Werdna.', 'The NES port of the legendary dungeon crawler.', 'One of the most influential RPGs, featuring a grid-based dungeon, permanent death, and deep party customization.');
