INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry---the-knight-of-diamonds-usa', 'NES', 'Wizardry - The Knight of Diamonds (USA)', '1992', 'RPG', 'Sir-Tech', '1', 'First-person', 'First-person RPG.', 'Recover the armor of the legendary knight.', 'The sequel to the first dungeon crawler.', 'Known for being even more difficult than the first, requiring a high-level party to survive the new, lethal dungeon floors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-ii---llylgamyn-no-densetsu-japan', 'NES', 'Wizardry II - Llylgamyn no Densetsu (Japan)', '1990', 'RPG', 'ASCII', '1', 'First-person', 'First-person RPG.', 'Explore the legend of Llylgamyn.', 'The Japanese Famicom version of the sequel.', 'Features updated graphics and a slightly more user-friendly interface compared to the original PC versions.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizardry-iii---diamond-no-kishi-japan', 'NES', 'Wizardry III - Diamond no Kishi (Japan)', '1991', 'RPG', 'ASCII', '1', 'First-person', 'First-person RPG.', 'Recover the magical orb to stop the earthquakes.', 'The third entry in the iconic RPG series.', 'It introduced the "Alignment" mechanic more deeply, where your party''s actions affect their stats and class options.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizards-&-warriors-europe', 'NES', 'Wizards & Warriors (Europe)', '1987', 'Action, Platform', 'Rare', '1', 'Side-scrolling', 'Action / Platformer.', 'Rescue the princesses from the wizard Malkil.', 'A classic fantasy adventure by Rare.', 'You play as Kuros, a knight who can jump incredibly high and collect various magical items and secondary weapons.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wizards-&-warriors-usa', 'NES', 'Wizards & Warriors (USA)', '1987', 'Action, Platform', 'Rare', '1', 'Side-scrolling', 'Action / Platformer.', 'Defeat Malkil and collect the diamonds.', 'The definitive US version of the brawler.', 'Famous for its catchy David Wise soundtrack and the frantic, "bouncy" feel of the platforming.');
