INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenophobe-usa', 'NES', 'Xenophobe (USA)', '1985', 'Shooter', 'Namco', '2', 'Vertical', 'Side-scrolling action.', 'Clear the space station of alien infestations.', 'A split-screen port of the arcade classic.', 'You explore multi-level stations, searching for keycards while blasting "Xenos" before time runs out.');
