INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xing-he-zhan-shi-china-unl', 'NES', 'Xing He Zhan Shi (China) (Unl)', '1991', 'Action', 'Unlicensed', '1', 'Side-scrolling', 'Turn-based RPG.', 'Embark on a Chinese sci-fi quest.', 'An unlicensed Chinese RPG (Star Warrior).', 'Features original art and a complex turn-based battle system typical of the late 90s bootlegs.');
